const BUILTIN = {"lessons":[{"id":"zoonoses","title":"Zoonotic Diseases & Host Specificity","icon":"🧬","pages":[1,2],"description":"How infections move between animals and people, including rabies, mosquito-borne disease, HIV, and host specificity.","sections":[{"title":"Zoonotic diseases","paragraphs":["Zoonotic diseases are infectious diseases transmitted between animals and humans. The reviewer lists Salmonella, Ebola, rabies, and SIV/HIV/AIDS as examples."],"bullets":["60% of known infectious diseases are described as zoonotic in the source.","75% of emerging infectious diseases are described as originating from wild or domestic animals.","Animal disease is described as causing 70% of global animal production losses."],"takeaway":"Zoonoses connect animal health with human health."},{"title":"Rabies","paragraphs":["Rabies is a viral disease that attacks the nervous system. The notes describe it as fatal once symptoms develop."],"bullets":["Spread: saliva of infected animals.","Human incubation: approximately two months in the reviewer (not a fixed interval).","Possible animal behavior: unusual lack of fear and marked agitation.","Symptoms listed: hydrophobia related to painful throat spasms, aggressiveness, and throat spasms."]},{"title":"Dengue and malaria","paragraphs":["The source contrasts two mosquito genera and their associated infections."],"table":{"headers":["Feature","Aedes mosquitoes / dengue","Anopheles mosquitoes / malaria"],"rows":[["Usual biting pattern","Aggressive daytime biter","Nighttime or crepuscular biter"],["Breeding","Still water","Various water sources"],["Diseases named","Dengue, Zika, yellow fever","Malaria; the notes also mention lymphatic filariasis and fever"],["Symptoms","High fever, severe headache, nausea/vomiting, muscle and joint pain, rash, low platelet count","High fever with chills, headache, fatigue, sweating"],["Additional note","Dengue is virus-associated","The reviewer says malaria can remain in the liver about 10 days to 4 weeks"]]},"note":"The original reviewer associates mosquito genera with these conditions; the table is a summary of the uploaded notes, not a complete entomological classification."},{"title":"SIV, HIV, and AIDS","paragraphs":["SIV (simian immunodeficiency virus) is described as a retrovirus infecting monkeys and apes. HIV attacks the body’s immune system, especially CD4 white blood cells. AIDS is the most advanced stage of HIV infection, associated with dangerously weakened immune defenses."],"bullets":["CD4 cells: coordinate immune responses and signal other immune cells.","CD8 cells: recognize and destroy virus-infected or cancerous cells."]},{"title":"Salmonella","paragraphs":["Salmonella is a bacterium linked to foodborne intestinal infection, including exposure to undercooked eggs or chicken."],"bullets":["Symptoms listed: diarrhea, fever, stomach cramps, nausea/vomiting, and headache."]},{"title":"Viral host specificity","paragraphs":["The tendency or ability of a virus to infect particular host species. Viruses require living host cells to replicate."],"bullets":["A virus must attach to a compatible host cell.","It must replicate inside the cell.","It must overcome host defenses.","Spillover also requires an opportunity to encounter a susceptible host; environmental and societal conditions influence contact."],"takeaway":"A virus may be biologically compatible with a new host, but exposure still matters."},{"title":"Bacterial host specificity","paragraphs":["The tendency of a bacterial species or strain to colonize or infect particular host species. Many bacteria can grow independently in suitable environmental conditions."],"bullets":["Bacteria must reach a suitable host location.","They must attach or establish colonization.","They must withstand the host’s defenses.","Contrast: viral specificity depends strongly on cell entry and replication; bacterial specificity depends on establishment, survival, and sometimes multiplication."]}]},{"id":"one-health","title":"Human Activity & One Health","icon":"🌍","pages":[3],"description":"Environmental changes that raise spillover opportunities, and the One Health approach.","sections":[{"title":"Human activities that drive spillover","bullets":["Habitat destruction and deforestation: agricultural expansion, logging, and urbanization fragment habitats, bringing wildlife closer to people and livestock.","Intensive livestock farming: closely housed, genetically similar animals under poor sanitary conditions facilitate pathogen amplification and potential transmission.","Wildlife trade and consumption: capture, transport, and live markets bring normally separated animal species into close contact.","Climate change and global travel: warmer ranges may change where disease vectors occur, while travel and trade can spread outbreaks across borders."],"takeaway":"Spillover risk depends on ecological conditions as well as pathogen biology."},{"title":"What is One Health?","paragraphs":["An integrated, collaborative approach recognizing that the health of people, animals, plants, and ecosystems is linked. It brings together human medicine, veterinary science, ecology, and agriculture to prevent disease, manage outbreaks, and support sustainable environmental policies."],"bullets":["The reviewer states that the One Health approach was developed in 2004.","Cross-sector programs, policies, legislation, and research are emphasized.","Four organizations named: WHO (World Health Organization), FAO (Food and Agriculture Organization), OIE (World Organisation for Animal Health, as named in the source), and UNEP (United Nations Environment Programme)."]},{"title":"Health and total wellness","paragraphs":["Health is described as complete physical, mental, and social well-being, not merely the absence of disease or infirmity.","Total wellness refers to holistic integration of physical, mental, and spiritual well-being; it fuels the body, engages the mind, and nurtures the spirit."]}]},{"id":"wellness","title":"Wellness & Health Hazards","icon":"🌱","pages":[4],"description":"The eight wellness dimensions, the difference between health and well-being, and major hazards.","sections":[{"title":"Eight dimensions of wellness","table":{"headers":["Dimension","Focus in the source"],"rows":[["Emotional","Coping effectively with life and creating satisfying relationships"],["Financial","Satisfaction with present and future financial circumstances"],["Social","Connection, belonging, and a support system"],["Spiritual","Sense of purpose and meaning in life"],["Occupational","Satisfaction and enrichment from work"],["Physical","Activity, diet, sleep, and nutrition"],["Intellectual","Creativity and expanding knowledge and skills"],["Environmental","Pleasant, stimulating environments supportive of well-being"]]}},{"title":"Health, well-being, and overall wellness","paragraphs":["The reviewer distinguishes well-being as a condition in which people are free to choose what they value doing or being. It says health and well-being co-determine one another.","Attaining wellness can be hindered by exposure to health hazards."]},{"title":"Health hazards","paragraphs":["The source discusses health hazards in terms of the probability or chance of harm from an agent capable of causing injury, illness, death, economic loss, or damage."],"table":{"headers":["Hazard type","Examples in the source"],"rows":[["Chemical","Harmful substances in air, water, soil, food, and human-made products"],["Natural","Fires, earthquakes, volcanic eruptions, floods, storms"],["Cultural","Unsafe workplaces/highways, criminal assault, poverty"],["Lifestyle","Smoking, poor diet, too much alcohol, unsafe sex"],["Biological","Disease-causing agents such as bacteria, viruses, parasites, protozoa, and fungi"]]},"note":"The reviewer mentions more than 1,400 pathogens that can infect humans; this is presented as a figure from the source."},{"title":"Pathogens and infectious disease","paragraphs":["A pathogen is a biological agent that can cause disease. The source explains infectious disease as invasion and multiplication by agents such as bacteria, viruses, or parasites inside body cells or tissues."],"bullets":["Examples given: tuberculosis, flu, malaria, and measles."]}]},{"id":"microbes","title":"Bacteria, Viruses & Antibiotic Resistance","icon":"🦠","pages":[5,6],"description":"Microbe biology, infection comparisons, resistance mechanisms, and ways resistance spreads.","sections":[{"title":"Bacteria","paragraphs":["Single-celled organisms found widely in the environment. Many are harmless or helpful; others cause disease as they multiply and spread."],"bullets":["Many bacteria reproduce independently under suitable conditions.","They have cell walls, which help protect them and maintain cell integrity.","The source discusses alcohol disinfection and recommends a concentration of about 65–75%; it notes pure alcohol evaporates too quickly."]},{"title":"Viruses","paragraphs":["Smaller than bacteria. They enter host cells and use cellular machinery to make more viruses. The reviewer classifies viruses as non-living entities."],"bullets":["Viruses require host cells to reproduce.","They can recognize and target particular types of cells.","Viruses do not have bacterial-type cell walls."]},{"title":"Bacteria vs. viruses","table":{"headers":["Category","Bacteria","Viruses"],"rows":[["Relative size","Generally bigger","Generally smaller"],["Source classification","Living","Non-living"],["Reproduction","Many can reproduce independently","Require host cells"],["Cell wall","Typically present (as described in the notes)","No bacterial-type cell wall"]]}},{"title":"Bacterial vs. viral infections","paragraphs":["The source gives typical classroom contrasts rather than universal diagnostic rules. The presence or spread of infection cannot, by itself, reliably determine whether it is bacterial or viral."],"table":{"headers":["In the PDF comparison","Bacterial infection","Viral infection"],"rows":[["Pattern described","Often localized, such as ear or throat","Described as systemic"],["Transmission","Sometimes contagious","Described as contagious"],["Antibiotics","May be treated with appropriate antibiotics","Not treated by antibiotics"],["Examples","Strep throat, pneumonia, urinary tract infection","Common cold, flu, chickenpox"]]},"note":"These are simplified contrasts taken from page 5. Some infections do not follow them; they should not be used to self-diagnose."},{"title":"How antibiotic resistance arises","bullets":["A bacterial population includes some naturally resistant variants.","Antibiotic exposure kills susceptible bacteria and can affect beneficial bacteria as well.","Resistant bacteria survive, multiply, and can become predominant when competition is reduced.","Resistance traits may be shared between bacteria, making treatment more challenging."]},{"title":"Drivers of antibiotic resistance","bullets":["Over-prescribing antibiotics.","Not following prescribed antibiotic treatment as directed.","Limited access to rapid tests for targeted treatment.","Unnecessary agricultural antibiotic use.","Weak infection control in health facilities.","Inadequate community hygiene and sanitation."]},{"title":"Spread of resistant bacteria","bullets":["Person-to-person transmission.","Food exposure, including improperly handled meat.","Contaminated manure or fertilizers reaching produce."]},{"title":"Transmissible vs. non-transmissible disease","table":{"headers":["Type","Meaning","Examples in source"],"rows":[["Transmissible / communicable","Infectious disease that spreads from person to person","Influenza, HIV, COVID-19"],["Non-transmissible / non-communicable","Does not spread from one person to another","Cardiovascular disease, most cancers"]]}}]},{"id":"health-threats","title":"Disease Transmission & SDG 3","icon":"🩺","pages":[7],"description":"Routes of transmission, outbreaks, historical mortality figures, and public-health goals.","sections":[{"title":"Routes into the human body","paragraphs":["The reviewer names these possible exposure sources or pathways:"],"bullets":["Pets","Livestock","Wild animals","Insects","Food","Water","Air","Other people and their body fluids"]},{"title":"Epidemics and pandemics","paragraphs":["Infectious diseases remain major health threats, especially in less-developed countries. The notes mention spread through air, water, food, and body fluids."],"bullets":["Epidemic: a large-scale outbreak in a particular area (local or regional).","Pandemic: an epidemic spreading across countries or internationally (global)."],"takeaway":"Epidemic emphasizes an outbreak within an area; pandemic emphasizes extensive international spread."},{"title":"Top 10 global causes of death: historical source table","paragraphs":["The reviewer labels this list as 2000–2016; it is historical, not a current ranking."],"bullets":["Ischaemic heart disease","Stroke","Lower respiratory infections","Chronic obstructive pulmonary disease","Diarrhoeal diseases","Tuberculosis","HIV/AIDS","Preterm birth complications","Trachea, bronchus, and lung cancers","Road injury"]},{"title":"Top 4 causes of death in the Philippines: 2011–2013","paragraphs":["The source lists heart disease, cerebrovascular disease (such as stroke), malignant neoplasm (cancer), and pneumonia."],"note":"The date range matters: do not interpret these as today’s top causes."},{"title":"SDG 3: Good Health and Well-being","paragraphs":["SDG 3 seeks to ensure healthy lives and promote well-being for all at all ages. The uploaded reviewer quotes a 2020 UN statement describing the human and economic disruption caused by COVID-19."],"takeaway":"Health is a central sustainable-development goal."}]},{"id":"covid","title":"COVID-19, Tests & Research","icon":"🔬","pages":[8,9],"description":"The historical COVID-19 timeline, test comparisons, and research in the Philippines.","sections":[{"title":"COVID-19 overview","paragraphs":["The original notes describe COVID-19 as a coronavirus-related disease first identified in Wuhan, China, among patients with pneumonia in December 2019. They describe investigation of animal sources, followed by human-to-human transmission."],"bullets":["The notes say “January 11, 2020 – still an epidemic” and “January 13, 2020 – became a pandemic.”","A later timeline in the SAME PDF dates the WHO pandemic declaration to March 11, 2020."],"note":"Source discrepancy: January 13 (page 8) conflicts with March 11 (page 9). Quizzes use the explicit March 11 WHO declaration from the source timeline, not the contradictory page 8 claim."},{"title":"COVID-19 diagnostic tests: comparison","table":{"headers":["Test","Sample","Detects","Strength in the notes","Limitation in the notes"],"rows":[["Rapid serology antibody test","Blood (finger prick or whole blood)","IgM/IgG antibodies","Simple and relatively fast; can be done outside a lab","Lower accuracy and possible false results; cross-reactivity"],["ELISA","Blood","IgM/IgG antibodies","More accurate laboratory antibody detection","Requires laboratory testing and assessment for cross-reactivity"],["RT-PCR","Nasal or throat swab","Viral RNA","Described as gold-standard for active infection","Requires trained personnel and equipment; notes flag timing sensitivity"]]},"note":"The table condenses page 8. Antibody tests and RNA tests measure different things. The reviewer’s original technical phrasing about “cDNA sequencing” has been preserved in the original-page transcript below."},{"title":"Research and contributors","paragraphs":["Dr. Raul Destura, a UST College of Science alumnus, is credited in the source with leading development of a local rRT-PCR detection kit.","The UST CoV-2 model is described as an epidemiological model that uses past spread to anticipate pandemic patterns. The source labels the NCR as the Philippines’ epidemiological epicenter at the time."]},{"title":"COVID-19 timeline","table":{"headers":["Date","Event in the uploaded reviewer"],"rows":[["December 2019","First cases reported in Wuhan, China"],["January 2020","Spread to other countries"],["March 11, 2020","WHO declares COVID-19 a pandemic; widespread restrictions in March"],["March 2020","Cases rise and hospitals face shortages"],["May–June 2020","Some countries ease restrictions despite continuing cases"],["July–November 2020","Mental-health and economic difficulties become more evident"],["December 2020","First vaccines approved"],["2021","Mass vaccination and emergence of new variants"]]}}]},{"id":"vaccines-history","title":"COVID Vaccines & Outbreak History","icon":"💉","pages":[10,11],"description":"Vaccine technology examples from the reviewer and a timeline of major disease-related events.","sections":[{"title":"COVID-19 vaccine comparison: historical notes","paragraphs":["The source table presents original vaccine dose schedules and advertised advantages as they were taught. Schedules and clinical recommendations can change; the table is kept as historical study material."],"table":{"headers":["Vaccine","Technology","Doses in PDF","Noted advantage"],"rows":[["Pfizer-BioNTech","mRNA","2","Very high effectiveness"],["Oxford-AstraZeneca","Viral vector","2","Widely available and affordable"],["Sinovac Corona","Inactivated virus","2","Traditional vaccine technology"],["Sputnik V","Viral vector","2","High reported effectiveness"],["Janssen","Viral vector","1","Single-dose vaccine"],["Bharat BioTech","Inactivated virus","2","Traditional vaccine technology"],["Moderna","mRNA","2","High effectiveness similar to Pfizer"],["Novavax","Protein subunit","2","Protein-based technology"]]},"note":"For reviewing the uploaded PDF only. This is not an updated dosing or vaccination recommendation."},{"title":"“What is the best vaccine?” — source framing","paragraphs":["The reviewer emphasizes vaccines that are immediately available, including subsidized options, and aims of reducing severe symptoms, hospitalization, and death.","The source states that all FDA-approved brands guarantee these functions. Treat that as a historical note from the PDF rather than an absolute medical guarantee; effectiveness and protection vary by product and context."]},{"title":"Warnings and pandemic preparedness","paragraphs":["The reviewer says the emergence of a virus-related pandemic had been anticipated in scientific discussions and mainstream media before COVID-19."]},{"title":"Historical public-health events","table":{"headers":["Year","Health event in PDF"],"rows":[["1955","Polio eradication efforts begin"],["1966","Smallpox eradication program launched"],["1976","Legionnaires’ disease identified; Ebola outbreak investigated"],["1981","HIV/AIDS first reported"],["1993","E. coli outbreak linked to Jack in the Box"],["2001","Anthrax attacks in the United States"],["2003","SARS outbreak"],["2014","Major Ebola outbreak"],["2015","HIV/hepatitis outbreak associated with opioid use"],["2016","Zika virus outbreak"],["2019","COVID-19 emerges"]]},"note":"The page heading calls these “Pandemics,” although the listed items also include outbreaks, attacks, and eradication initiatives. They are reproduced as source events, not all classified as pandemics."}]}],"cards":[{"id":"c1","lesson":"zoonoses","front":"Infectious diseases transmitted between animals and humans.","back":"Zoonotic diseases","detail":"Examples: rabies, Salmonella, and Ebola.","page":1},{"id":"c2","lesson":"zoonoses","front":"Fatal nervous-system viral infection transmitted through infected animal saliva.","back":"Rabies","detail":"The reviewer mentions hydrophobia, agitation, and throat spasms.","page":1},{"id":"c3","lesson":"zoonoses","front":"Aggressive mosquito genus commonly biting during the day and associated with dengue.","back":"Aedes","detail":"Also associated in the source with Zika and yellow fever.","page":1},{"id":"c4","lesson":"zoonoses","front":"Mosquito genus commonly biting at night and associated with malaria.","back":"Anopheles","detail":"The source calls its pattern crepuscular/nighttime.","page":1},{"id":"c5","lesson":"zoonoses","front":"Disease characterized in the source by high fever, headache, joint pain, rash, and low platelets.","back":"Dengue","detail":"Discussed in the Aedes comparison.","page":1},{"id":"c6","lesson":"zoonoses","front":"Mosquito-borne disease associated with fever and chills and a stage in the liver.","back":"Malaria","detail":"Associated in the source with Anopheles.","page":1},{"id":"c7","lesson":"zoonoses","front":"Retrovirus that infects monkeys and apes.","back":"SIV","detail":"Simian immunodeficiency virus.","page":1},{"id":"c8","lesson":"zoonoses","front":"Virus targeting the immune system, especially CD4 cells.","back":"HIV","detail":"An untreated HIV infection can advance to AIDS.","page":1},{"id":"c9","lesson":"zoonoses","front":"Advanced stage of infection caused by HIV with severely weakened immunity.","back":"AIDS","detail":"The source calls it the most advanced stage.","page":1},{"id":"c10","lesson":"zoonoses","front":"Immune cells that coordinate responses and signal other immune cells.","back":"CD4 cells","detail":"The source uses the metaphor “commanders.”","page":1},{"id":"c11","lesson":"zoonoses","front":"Immune cells that destroy infected or cancerous cells.","back":"CD8 cells","detail":"The source uses the metaphor “soldiers.”","page":1},{"id":"c12","lesson":"zoonoses","front":"Foodborne bacterium associated with undercooked eggs or chicken.","back":"Salmonella","detail":"Symptoms include diarrhea, cramps, fever, nausea.","page":2},{"id":"c13","lesson":"zoonoses","front":"Tendency of a virus to infect particular host species.","back":"Viral host specificity","detail":"Requires compatible cell attachment, replication, and overcoming defenses.","page":2},{"id":"c14","lesson":"zoonoses","front":"Tendency of bacteria to colonize or infect particular host species.","back":"Bacterial host specificity","detail":"Requires suitable site, colonization, and survival.","page":2},{"id":"c15","lesson":"zoonoses","front":"Cross-species transfer of an infectious agent from an animal host into humans.","back":"Zoonotic spillover","detail":"Biological compatibility and exposure opportunities both matter.","page":2},{"id":"c16","lesson":"one-health","front":"Clearing and fragmenting natural habitats, bringing wildlife closer to human settlements.","back":"Habitat destruction / deforestation","detail":"One human-associated driver of zoonotic spillover.","page":3},{"id":"c17","lesson":"one-health","front":"Dense animal rearing that can help pathogens amplify and spread.","back":"Intensive livestock farming","detail":"An activity associated with spillover risk.","page":3},{"id":"c18","lesson":"one-health","front":"Trading and transporting wild animals that would rarely encounter one another naturally.","back":"Wildlife trade and consumption","detail":"Can create unusual interspecies contacts.","page":3},{"id":"c19","lesson":"one-health","front":"Collaborative public-health approach connecting human, animal, plant, and ecosystem health.","back":"One Health","detail":"Integrates different professional sectors.","page":3},{"id":"c20","lesson":"one-health","front":"UN agency focused on international public health; a One Health partner in the notes.","back":"WHO","detail":"World Health Organization.","page":3},{"id":"c21","lesson":"one-health","front":"UN organization for food and agriculture; listed as a One Health partner.","back":"FAO","detail":"Food and Agriculture Organization.","page":3},{"id":"c22","lesson":"one-health","front":"Animal-health organization named as OIE in the reviewer.","back":"OIE","detail":"World Organisation for Animal Health, named in the source as a partner.","page":3},{"id":"c23","lesson":"one-health","front":"UN body for environmental issues, listed in One Health collaboration.","back":"UNEP","detail":"United Nations Environment Programme.","page":3},{"id":"c24","lesson":"one-health","front":"Complete physical, mental, and social well-being, not simply absence of disease.","back":"Health","detail":"Definition reproduced from page 3.","page":3},{"id":"c25","lesson":"one-health","front":"Integration of physical, mental, and spiritual well-being.","back":"Total wellness","detail":"The reviewer calls it holistic integration.","page":3},{"id":"c26","lesson":"wellness","front":"Wellness dimension about handling life effectively and relationships.","back":"Emotional wellness","detail":"One of eight dimensions.","page":4},{"id":"c27","lesson":"wellness","front":"Wellness dimension about satisfaction with current and future finances.","back":"Financial wellness","detail":"One of eight dimensions.","page":4},{"id":"c28","lesson":"wellness","front":"Wellness dimension centered on belonging and support systems.","back":"Social wellness","detail":"One of eight dimensions.","page":4},{"id":"c29","lesson":"wellness","front":"Wellness dimension centered on meaning and purpose.","back":"Spiritual wellness","detail":"One of eight dimensions.","page":4},{"id":"c30","lesson":"wellness","front":"Wellness dimension about satisfaction and enrichment from work.","back":"Occupational wellness","detail":"One of eight dimensions.","page":4},{"id":"c31","lesson":"wellness","front":"Wellness dimension involving activity, food, sleep, and nutrition.","back":"Physical wellness","detail":"One of eight dimensions.","page":4},{"id":"c32","lesson":"wellness","front":"Wellness dimension involving curiosity, creativity, and learning.","back":"Intellectual wellness","detail":"One of eight dimensions.","page":4},{"id":"c33","lesson":"wellness","front":"Wellness dimension involving surroundings supportive of good health.","back":"Environmental wellness","detail":"One of eight dimensions.","page":4},{"id":"c34","lesson":"wellness","front":"The freedom to choose to do and be what one values, according to the reviewer.","back":"Well-being","detail":"Contrasted with health states on page 4.","page":4},{"id":"c35","lesson":"wellness","front":"Probability of harm from something that can cause disease, injury, or other loss.","back":"Health hazard","detail":"Source describes health hazards as risk/chances.","page":4},{"id":"c36","lesson":"wellness","front":"Hazards arising from harmful substances in the environment or products.","back":"Chemical hazards","detail":"May occur in air, water, soil, food, products.","page":4},{"id":"c37","lesson":"wellness","front":"Hazards involving earthquakes, floods, storms, and volcanic activity.","back":"Natural hazards","detail":"Examples from the reviewer.","page":4},{"id":"c38","lesson":"wellness","front":"Hazards involving unsafe workplaces, roads, violence, or poverty.","back":"Cultural hazards","detail":"Source category on page 4.","page":4},{"id":"c39","lesson":"wellness","front":"Hazards resulting from personal choices such as smoking or unsafe sex.","back":"Lifestyle choices","detail":"Source category on page 4.","page":4},{"id":"c40","lesson":"wellness","front":"Hazards involving disease-causing bacteria, viruses, parasites, or fungi.","back":"Biological hazards","detail":"Include pathogens.","page":4},{"id":"c41","lesson":"wellness","front":"Biological agent capable of causing disease in another organism.","back":"Pathogen","detail":"The reviewer gives multiple pathogen types.","page":4},{"id":"c42","lesson":"wellness","front":"Disease in which a pathogen invades and multiplies in the body.","back":"Infectious disease","detail":"Examples: tuberculosis, flu, malaria, measles.","page":4},{"id":"c43","lesson":"microbes","front":"Single-celled living organisms, many harmless or beneficial, that may reproduce independently.","back":"Bacteria","detail":"Discussed on page 5.","page":5},{"id":"c44","lesson":"microbes","front":"Cell-dependent infectious entities that use host machinery to multiply.","back":"Viruses","detail":"The notes characterize them as non-living.","page":5},{"id":"c45","lesson":"microbes","front":"Protective outer structure present in most bacterial cells but absent in viruses.","back":"Bacterial cell wall","detail":"A contrast in the source table.","page":5},{"id":"c46","lesson":"microbes","front":"Drug treatment used against susceptible bacterial infections, not viruses.","back":"Antibiotics","detail":"Misuse contributes to resistance.","page":5},{"id":"c47","lesson":"microbes","front":"Ability of bacteria to survive antibiotic exposure and multiply.","back":"Antibiotic resistance","detail":"Resistance can spread through selection or genetic transfer.","page":6},{"id":"c48","lesson":"microbes","front":"An initial small group of bacteria unaffected by an antibiotic.","back":"Resistant variants","detail":"They may dominate after sensitive bacteria die.","page":6},{"id":"c49","lesson":"microbes","front":"Sharing drug-resistance traits between bacterial strains.","back":"Resistance transfer","detail":"A mechanism described on page 6.","page":6},{"id":"c50","lesson":"microbes","front":"Spread of infections between people, including resistant bacteria.","back":"Person-to-person transmission","detail":"One resistance dissemination route.","page":6},{"id":"c51","lesson":"microbes","front":"Disease that can spread from person to person; also called communicable.","back":"Transmissible disease","detail":"Examples: influenza, HIV, COVID-19.","page":6},{"id":"c52","lesson":"microbes","front":"Disease that does not spread person to person; also called non-communicable.","back":"Non-transmissible disease","detail":"Examples include heart disease and most cancers.","page":6},{"id":"c53","lesson":"health-threats","front":"Outbreak of infectious disease affecting many people in a particular area.","back":"Epidemic","detail":"The source labels it “LOCAL.”","page":7},{"id":"c54","lesson":"health-threats","front":"Epidemic with extensive spread across countries or the world.","back":"Pandemic","detail":"The source labels it “GLOBAL.”","page":7},{"id":"c55","lesson":"health-threats","front":"Sustainable Development Goal focused on healthy lives and well-being for all ages.","back":"SDG 3","detail":"Good Health and Well-being.","page":7},{"id":"c56","lesson":"health-threats","front":"Heart condition identified as the top cause in the source’s 2000–2016 global mortality list.","back":"Ischaemic heart disease","detail":"A historical ranking, not a current ranking.","page":7},{"id":"c57","lesson":"health-threats","front":"Philippine 2011–2013 mortality category that includes stroke.","back":"Cerebrovascular diseases","detail":"One of four listed causes.","page":7},{"id":"c58","lesson":"health-threats","front":"Respiratory infection listed among the 2011–2013 Philippine causes of death.","back":"Pneumonia","detail":"One of four source categories.","page":7},{"id":"c59","lesson":"covid","front":"Coronavirus disease first identified in Wuhan during late 2019.","back":"COVID-19","detail":"Discussed in the source historical timeline.","page":8},{"id":"c60","lesson":"covid","front":"Quick blood-based test for IgM/IgG antibodies discussed in the PDF.","back":"Rapid serology antibody test","detail":"Not a direct viral RNA detection test.","page":8},{"id":"c61","lesson":"covid","front":"Laboratory blood-based assay used to detect antibodies in the PDF.","back":"ELISA test","detail":"Antibody test with laboratory requirements.","page":8},{"id":"c62","lesson":"covid","front":"Test using a nasal or throat sample to detect viral RNA.","back":"RT-PCR test","detail":"The source calls it a gold-standard for active infection.","page":8},{"id":"c63","lesson":"covid","front":"Molecules such as IgM and IgG measured by serology and ELISA in the COVID testing table.","back":"Antibodies","detail":"Different from direct measurement of viral RNA.","page":8},{"id":"c64","lesson":"covid","front":"UST College of Science alumnus credited with developing a local rRT-PCR detection kit.","back":"Dr. Raul Destura","detail":"Referenced on page 9.","page":9},{"id":"c65","lesson":"covid","front":"UST epidemiological model forecasting pandemic spread from earlier patterns.","back":"UST CoV-2 Model","detail":"Source research highlight.","page":9},{"id":"c66","lesson":"covid","front":"Date of WHO COVID-19 pandemic declaration in the source timeline.","back":"March 11, 2020","detail":"Page 9 conflicts with page 8’s January 13 statement; timeline date used.","page":9},{"id":"c67","lesson":"vaccines-history","front":"COVID-19 vaccine technology used by Pfizer-BioNTech and Moderna in the PDF.","back":"mRNA","detail":"Both have two original doses in the source table.","page":10},{"id":"c68","lesson":"vaccines-history","front":"Vaccine technology listed for AstraZeneca, Sputnik V, and Janssen.","back":"Viral vector","detail":"Source vaccine table.","page":10},{"id":"c69","lesson":"vaccines-history","front":"Vaccine technology listed for Sinovac Corona and Bharat BioTech.","back":"Inactivated virus","detail":"Source vaccine table.","page":10},{"id":"c70","lesson":"vaccines-history","front":"Vaccine technology listed for Novavax.","back":"Protein subunit","detail":"Source vaccine table.","page":10},{"id":"c71","lesson":"vaccines-history","front":"Viral-vector vaccine listed with one original dose in the source table.","back":"Janssen","detail":"Dose schedules shown are historical.","page":10},{"id":"c72","lesson":"vaccines-history","front":"Year in the source table when SARS outbreak occurred.","back":"2003","detail":"Page 11 historical event list.","page":11},{"id":"c73","lesson":"vaccines-history","front":"Year the source marks as first reports of HIV/AIDS.","back":"1981","detail":"Page 11 historical events.","page":11},{"id":"c74","lesson":"vaccines-history","front":"Year of the major Ebola outbreak in the source history.","back":"2014","detail":"Page 11 historical events.","page":11},{"id":"c75","lesson":"vaccines-history","front":"Year of the Zika outbreak in the source history.","back":"2016","detail":"Page 11 historical events.","page":11},{"id":"c76","lesson":"vaccines-history","front":"Year of the Jack in the Box-related E. coli outbreak in the PDF.","back":"1993","detail":"Page 11 historical events.","page":11},{"id":"c77","lesson":"vaccines-history","front":"Year in which the source places the smallpox eradication program launch.","back":"1966","detail":"Page 11 historical events.","page":11}],"questions":[{"id":"q1","lesson":"zoonoses","difficulty":"Easy","prompt":"Which best defines a zoonotic disease?","choices":["An infectious disease transmitted between animals and humans","A disease that affects only plants","A non-infectious inherited condition","An infection that cannot affect animals"],"answer":0,"explanation":"Page 1 defines zoonotic diseases as infections transmitted between animals and humans.","page":1},{"id":"q2","lesson":"zoonoses","difficulty":"Easy","prompt":"Which disease in the notes is transmitted via the saliva of an infected animal?","choices":["Rabies","Malaria","Dengue","Salmonella"],"answer":0,"explanation":"Rabies is described as spreading through infected animal saliva (p. 1).","page":1},{"id":"q3","lesson":"zoonoses","difficulty":"Easy","prompt":"Which mosquito genus is described as a daytime biter?","choices":["Aedes","Anopheles","Culex (not described)","Neither mosquito genus"],"answer":0,"explanation":"The Aedes mosquito is specifically described as a daytime biter (p. 1).","page":1},{"id":"q4","lesson":"zoonoses","difficulty":"Easy","prompt":"Which mosquito genus is associated with malaria in the reviewer?","choices":["Anopheles","Aedes","Honeybee","Housefly"],"answer":0,"explanation":"Page 1 associates malaria with Anopheles mosquitoes.","page":1},{"id":"q5","lesson":"zoonoses","difficulty":"Moderate","prompt":"Which symptom cluster best matches dengue in the uploaded notes?","choices":["High fever, severe headache, rash, low platelet count","Fever with chills and liver dormancy","Hydrophobia and throat spasms","Intestinal cramps after undercooked eggs"],"answer":0,"explanation":"Page 1 lists fever, headache, rash and low platelets among dengue symptoms.","page":1},{"id":"q6","lesson":"zoonoses","difficulty":"Moderate","prompt":"Which immune cells are described as coordinating an immune response?","choices":["CD4 cells","CD8 cells","Red blood cells","Platelets"],"answer":0,"explanation":"The source calls CD4 cells the “commanders” that signal other immune cells (p. 1).","page":1},{"id":"q7","lesson":"zoonoses","difficulty":"Moderate","prompt":"Which statement distinguishes HIV from AIDS?","choices":["HIV is the virus; AIDS is the most advanced stage of HIV infection","HIV is a bacterium; AIDS is a virus","HIV and AIDS refer only to animal infections","AIDS is caused by malaria"],"answer":0,"explanation":"Page 1 describes HIV targeting the immune system and AIDS as an advanced HIV stage.","page":1},{"id":"q8","lesson":"zoonoses","difficulty":"Moderate","prompt":"Which food exposure is specifically linked with Salmonella?","choices":["Undercooked eggs or chicken","Unwashed fruit as the only source","A mosquito bite","Infected animal saliva"],"answer":0,"explanation":"Page 2 links Salmonella with undercooked eggs/chicken.","page":2},{"id":"q9","lesson":"zoonoses","difficulty":"Difficult","prompt":"What additional condition must be met for viral spillover beyond biological host compatibility?","choices":["The virus must encounter a susceptible host","The virus must become a bacterium","All viruses must first reproduce in water","The host must have a bacterial cell wall"],"answer":0,"explanation":"Page 2 stresses that compatible viruses also need a chance to encounter a susceptible host.","page":2},{"id":"q10","lesson":"zoonoses","difficulty":"Difficult","prompt":"Which process matters specifically for bacterial host specificity in the PDF?","choices":["Colonization and survival at a suitable host site","Direct production of virus particles","Entry into every type of host cell","Dependency on host machinery to reproduce"],"answer":0,"explanation":"Page 2 contrasts bacterial colonization/survival with viral cell entry and replication.","page":2},{"id":"q11","lesson":"zoonoses","difficulty":"Difficult","prompt":"Why can viruses not reproduce independently according to the notes?","choices":["They need living cellular machinery to form new viral particles","They must always share antibiotic-resistance genes","They consist of multiple independent cells","They reproduce only on inanimate surfaces"],"answer":0,"explanation":"The page 2 explanation requires host cells for viral replication.","page":2},{"id":"q12","lesson":"one-health","difficulty":"Easy","prompt":"What does the One Health framework connect?","choices":["Human, animal, plant, and ecosystem health","Only human medical treatment","Only wildlife conservation without people","Only vaccination schedules"],"answer":0,"explanation":"The source explicitly connects the health of people, animals, plants and ecosystems (p. 3).","page":3},{"id":"q13","lesson":"one-health","difficulty":"Easy","prompt":"Which agency is the World Health Organization?","choices":["WHO","FAO","OIE","UNEP"],"answer":0,"explanation":"WHO expands to World Health Organization in the One Health organizations list.","page":3},{"id":"q14","lesson":"one-health","difficulty":"Moderate","prompt":"How does habitat destruction contribute to zoonotic spillover?","choices":["It brings wildlife closer to humans and livestock","It makes all pathogens harmless","It removes the need for hosts","It stops all animal-human contact"],"answer":0,"explanation":"Page 3 describes fragmentation pushing wildlife toward human settlements and livestock.","page":3},{"id":"q15","lesson":"one-health","difficulty":"Moderate","prompt":"Which activity mixes animal species that might not naturally meet?","choices":["Wildlife trade and live markets","Remote learning","Routine sleep","Reading epidemiological reports"],"answer":0,"explanation":"The wildlife trade section states that capture/transport/live markets mix species (p. 3).","page":3},{"id":"q16","lesson":"one-health","difficulty":"Moderate","prompt":"Which organization in the reviewer focuses on food and agriculture?","choices":["FAO","WHO","OIE","UNEP"],"answer":0,"explanation":"FAO stands for Food and Agriculture Organization (p. 3).","page":3},{"id":"q17","lesson":"one-health","difficulty":"Difficult","prompt":"Why can climate change and global travel jointly increase outbreak risk?","choices":["Vectors may expand their ranges and travel can spread local outbreaks","They make bacteria unable to divide","They eliminate animal-human exposure","They guarantee every virus becomes zoonotic"],"answer":0,"explanation":"Both altered vector range and international mobility are listed as drivers (p. 3).","page":3},{"id":"q18","lesson":"one-health","difficulty":"Difficult","prompt":"Which phrase most closely matches “total wellness” in the reviewer?","choices":["Holistic physical, mental, and spiritual well-being","Complete absence of all microorganisms","Only economic satisfaction","A test result for active COVID infection"],"answer":0,"explanation":"Page 3 defines total wellness as holistic integration of these aspects.","page":3},{"id":"q19","lesson":"wellness","difficulty":"Easy","prompt":"Which wellness dimension concerns money and future finances?","choices":["Financial","Social","Physical","Environmental"],"answer":0,"explanation":"The financial dimension concerns satisfaction with present/future finances (p. 4).","page":4},{"id":"q20","lesson":"wellness","difficulty":"Easy","prompt":"Which wellness dimension focuses on belonging and support systems?","choices":["Social","Occupational","Intellectual","Chemical"],"answer":0,"explanation":"Page 4 connects social wellness with belonging and support.","page":4},{"id":"q21","lesson":"wellness","difficulty":"Moderate","prompt":"Which dimension emphasizes expanding knowledge and skills?","choices":["Intellectual","Financial","Environmental","Occupational"],"answer":0,"explanation":"Intellectual wellness concerns creativity and developing knowledge and skills (p. 4).","page":4},{"id":"q22","lesson":"wellness","difficulty":"Moderate","prompt":"Which category contains earthquakes, floods, and storms?","choices":["Natural hazards","Cultural hazards","Chemical hazards","Lifestyle choices"],"answer":0,"explanation":"Page 4 lists these as natural hazards.","page":4},{"id":"q23","lesson":"wellness","difficulty":"Moderate","prompt":"How does the PDF describe well-being in contrast to health states?","choices":["Freedom to do and be what people value","Strictly the absence of infection","Exactly the same as financial satisfaction","Only eating and exercise routines"],"answer":0,"explanation":"Well-being is framed as freedom to choose valued activities and states (p. 4).","page":4},{"id":"q24","lesson":"wellness","difficulty":"Difficult","prompt":"A poorly maintained highway fits which hazard category in the source?","choices":["Cultural hazards","Biological hazards","Natural hazards","Chemical hazards"],"answer":0,"explanation":"Unsafe highways are given as examples of cultural hazards (p. 4).","page":4},{"id":"q25","lesson":"wellness","difficulty":"Difficult","prompt":"What is a pathogen?","choices":["A biological agent capable of causing disease","Every living organism","A type of antibiotic","An indicator of financial wellness"],"answer":0,"explanation":"The definition appears within biological hazards on page 4.","page":4},{"id":"q26","lesson":"microbes","difficulty":"Easy","prompt":"Which statement best describes viruses in the PDF?","choices":["They require host cells to reproduce","They always divide independently","They are larger than all bacteria","They contain bacterial cell walls"],"answer":0,"explanation":"Page 5 says viruses need host cells to multiply.","page":5},{"id":"q27","lesson":"microbes","difficulty":"Easy","prompt":"Which treatment does the PDF say does not work against viral infections?","choices":["Antibiotics","Rest and supportive care","Preventive vaccination","Laboratory diagnosis"],"answer":0,"explanation":"Page 5 contrasts antibiotic treatment of bacterial infections with viral infections.","page":5},{"id":"q28","lesson":"microbes","difficulty":"Moderate","prompt":"Which property differentiates bacteria from viruses in the reviewer?","choices":["Many bacteria can reproduce independently","All bacteria are non-living","Bacteria never have cell walls","Bacteria depend on host cells for all reproduction"],"answer":0,"explanation":"Page 5 says bacteria can reproduce independently while viruses require a host.","page":5},{"id":"q29","lesson":"microbes","difficulty":"Moderate","prompt":"What happens to resistant variants after susceptible bacteria are killed?","choices":["They may multiply and dominate the population","They automatically become viruses","They lose all genetic traits","They can no longer reproduce"],"answer":0,"explanation":"Page 6 describes survivors expanding after antibiotics remove competition.","page":6},{"id":"q30","lesson":"microbes","difficulty":"Moderate","prompt":"Which is a cause of antibiotic resistance in the notes?","choices":["Unnecessary antibiotics in agriculture","Completing proper diagnostic tests","Improved hospital hygiene","Reducing unnecessary antibiotic use"],"answer":0,"explanation":"The reviewer includes agricultural overuse as a driver (p. 6).","page":6},{"id":"q31","lesson":"microbes","difficulty":"Moderate","prompt":"Which is an example of a non-transmissible disease in the reviewer?","choices":["Cardiovascular disease","Influenza","COVID-19","HIV infection"],"answer":0,"explanation":"Cardiovascular disease is listed as non-communicable (p. 6).","page":6},{"id":"q32","lesson":"microbes","difficulty":"Difficult","prompt":"How can resistance spread between bacterial strains?","choices":["Transfer of drug-resistance traits","Conversion of bacteria into protozoa","Direct copying of virus RNA only","Creation of new CD4 cells"],"answer":0,"explanation":"Page 6 describes resistance-trait transfer among bacteria.","page":6},{"id":"q33","lesson":"microbes","difficulty":"Difficult","prompt":"Which route is specifically described as spreading resistant bacteria into produce?","choices":["Contaminated manure used as fertilizer","A solar eclipse","Direct spread through sunlight","A change in vaccine type"],"answer":0,"explanation":"Page 6 notes manure/fertilizers can introduce bacteria onto vegetables.","page":6},{"id":"q34","lesson":"microbes","difficulty":"Difficult","prompt":"Which alcohol concentration does the reviewer describe as effective for disinfection?","choices":["65–75%","0–5%","10–15%","100% only"],"answer":0,"explanation":"Page 5 recommends 65–75% alcohol and says pure alcohol evaporates quickly.","page":5},{"id":"q35","lesson":"microbes","difficulty":"Difficult","prompt":"Which pair correctly matches disease categories with source examples?","choices":["Transmissible: influenza; non-transmissible: heart disease","Transmissible: heart disease; non-transmissible: influenza","Transmissible: most cancers; non-transmissible: HIV","Transmissible: stroke; non-transmissible: COVID-19"],"answer":0,"explanation":"These examples appear in the page 6 classification table.","page":6},{"id":"q36","lesson":"health-threats","difficulty":"Easy","prompt":"What term denotes a large-scale outbreak in an area?","choices":["Epidemic","Endemic host specificity","Antibiotic resistance","ELISA"],"answer":0,"explanation":"Page 7 defines an epidemic as a large-scale outbreak in an area.","page":7},{"id":"q37","lesson":"health-threats","difficulty":"Easy","prompt":"Which Sustainable Development Goal focuses on health and well-being?","choices":["SDG 3","SDG 1","SDG 12","SDG 16"],"answer":0,"explanation":"The source heading is “SDG 3 GOOD HEALTH AND WELLBEING” (p. 7).","page":7},{"id":"q38","lesson":"health-threats","difficulty":"Moderate","prompt":"Which is listed as a possible route of infectious-disease entry?","choices":["Air","Only inherited genes","Only ultraviolet light","Only financial transactions"],"answer":0,"explanation":"Air appears among the pathways listed on page 7.","page":7},{"id":"q39","lesson":"health-threats","difficulty":"Moderate","prompt":"Which was listed among the Philippines’ top four causes of death in 2011–2013?","choices":["Pneumonia","Dengue as the only cause","Zika virus","Rabies as the leading cause"],"answer":0,"explanation":"Page 7 includes pneumonia in the historical top-four list.","page":7},{"id":"q40","lesson":"health-threats","difficulty":"Difficult","prompt":"Which was in the PDF’s 2000–2016 top global causes of death list?","choices":["Lower respiratory infections","Hay fever","Mild acne","Short-term muscle soreness"],"answer":0,"explanation":"The historical global list on page 7 names lower respiratory infections.","page":7},{"id":"q41","lesson":"health-threats","difficulty":"Difficult","prompt":"What is the key difference between epidemic and pandemic in the reviewer?","choices":["Geographic scale of spread","Whether the illness is bacterial by definition","Whether only animals can catch it","Whether there is an antibiotic available"],"answer":0,"explanation":"Page 7 labels epidemic local and pandemic global.","page":7},{"id":"q42","lesson":"covid","difficulty":"Easy","prompt":"Which test in the PDF detects COVID-19 viral RNA?","choices":["RT-PCR","Rapid serology","ELISA antibody test","Financial screening"],"answer":0,"explanation":"The page 8 testing table identifies RT-PCR as an RNA test.","page":8},{"id":"q43","lesson":"covid","difficulty":"Easy","prompt":"Which two tests in the PDF detect antibodies rather than viral RNA?","choices":["Rapid serology and ELISA","RT-PCR and CT scan","RT-PCR and viral culture","RT-PCR and PCR sequencing"],"answer":0,"explanation":"The comparison table lists rapid serology and ELISA as IgM/IgG tests (p. 8).","page":8},{"id":"q44","lesson":"covid","difficulty":"Moderate","prompt":"Which sample type is associated with RT-PCR in the source?","choices":["Nasal or throat swab","Only a stool sample","Hair strand","Skin biopsy"],"answer":0,"explanation":"The page 8 table lists a nose/throat swab.","page":8},{"id":"q45","lesson":"covid","difficulty":"Moderate","prompt":"Who led the local rRT-PCR detection kit development highlighted on page 9?","choices":["Dr. Raul Destura","Dr. Jose Rizal","Louis Pasteur","Edward Jenner"],"answer":0,"explanation":"Page 9 identifies Dr. Raul Destura, a UST alumnus.","page":9},{"id":"q46","lesson":"covid","difficulty":"Moderate","prompt":"On what date does the source timeline say WHO declared COVID-19 a pandemic?","choices":["March 11, 2020","December 25, 2019","March 11, 2021","December 11, 2020"],"answer":0,"explanation":"The page 9 timeline gives March 11, 2020; page 8 contains a conflicting January claim.","page":9},{"id":"q47","lesson":"covid","difficulty":"Difficult","prompt":"What is the described function of the UST CoV-2 Model?","choices":["Predict pandemic behavior using earlier spread patterns","Detect antibodies using a finger prick","Sequence every vaccine protein","Replace all clinical lab tests"],"answer":0,"explanation":"Page 9 calls it an epidemiological forecasting model.","page":9},{"id":"q48","lesson":"covid","difficulty":"Difficult","prompt":"Which concern is listed as a limitation of rapid serology?","choices":["Possible false results and cross-reactivity","Detects viral RNA directly","Requires a nose swab for every test","Always detects infection before symptoms"],"answer":0,"explanation":"Page 8 lists false results and cross-reactivity issues.","page":8},{"id":"q49","lesson":"covid","difficulty":"Difficult","prompt":"Which event is placed in December 2020 by the source timeline?","choices":["First COVID-19 vaccine approvals","The WHO pandemic declaration","The SARS outbreak","The Zika outbreak"],"answer":0,"explanation":"Page 9 lists the first vaccine approvals in December 2020.","page":9},{"id":"q50","lesson":"vaccines-history","difficulty":"Easy","prompt":"Which vaccine technology is listed for Pfizer-BioNTech?","choices":["mRNA","Protein subunit","Inactivated virus","Bacterial culture"],"answer":0,"explanation":"Page 10 lists Pfizer-BioNTech as an mRNA vaccine.","page":10},{"id":"q51","lesson":"vaccines-history","difficulty":"Easy","prompt":"Which vaccine is listed as a protein-subunit product?","choices":["Novavax","Sinovac Corona","Janssen","Moderna"],"answer":0,"explanation":"Page 10 lists Novavax as protein subunit.","page":10},{"id":"q52","lesson":"vaccines-history","difficulty":"Moderate","prompt":"Which vaccine is listed as having one original dose in the PDF?","choices":["Janssen","Moderna","Pfizer-BioNTech","Oxford-AstraZeneca"],"answer":0,"explanation":"Page 10 lists Janssen with one dose in the historical table.","page":10},{"id":"q53","lesson":"vaccines-history","difficulty":"Moderate","prompt":"Which pair is identified as inactivated-virus vaccines?","choices":["Sinovac Corona and Bharat BioTech","Pfizer-BioNTech and Moderna","Novavax and Janssen","Sputnik V and Oxford-AstraZeneca"],"answer":0,"explanation":"The source vaccine table lists these two as inactivated virus (p. 10).","page":10},{"id":"q54","lesson":"vaccines-history","difficulty":"Moderate","prompt":"In which year does the source list the SARS outbreak?","choices":["2003","1981","2016","1955"],"answer":0,"explanation":"Page 11 associates SARS with 2003.","page":11},{"id":"q55","lesson":"vaccines-history","difficulty":"Moderate","prompt":"Which outbreak is listed for 2014?","choices":["Major Ebola outbreak","COVID-19 emergence","2001 anthrax attacks","SARS outbreak"],"answer":0,"explanation":"The page 11 historical table gives the major Ebola outbreak in 2014.","page":11},{"id":"q56","lesson":"vaccines-history","difficulty":"Difficult","prompt":"Which year is linked to an E. coli outbreak at Jack in the Box?","choices":["1993","1976","2001","2019"],"answer":0,"explanation":"Page 11 dates the cited E. coli outbreak to 1993.","page":11},{"id":"q57","lesson":"vaccines-history","difficulty":"Difficult","prompt":"Which technology is common to AstraZeneca, Sputnik V and Janssen in the source table?","choices":["Viral vector","mRNA","Inactivated virus","Protein subunit"],"answer":0,"explanation":"All three are viral-vector vaccines in the page 10 table.","page":10},{"id":"q58","lesson":"vaccines-history","difficulty":"Difficult","prompt":"What did the reviewer emphasize when discussing the best vaccine?","choices":["Availability and reducing severe outcomes","Choosing by the longest brand name","Always requiring one dose","Ignoring hospitalization risk"],"answer":0,"explanation":"The page 10 notes emphasize timely availability and prevention of severe illness/hospitalization/death.","page":10},{"id":"q59","lesson":"vaccines-history","difficulty":"Difficult","prompt":"Which public-health event is associated with 1966 in the PDF?","choices":["Smallpox eradication program launched","COVID-19 emerging","Zika outbreak","HIV/AIDS first reported"],"answer":0,"explanation":"Page 11’s timeline gives the smallpox program launch in 1966.","page":11}],"sourcePages":[{"page":1,"text":"ONE HEALTH \n \n● Zoonotic Diseases \n○ Infectious diseases that are transmitted between animals and humans. \n○ E.g., Salmonella, Ebola, Rabies, SIV/HIV/AIDS \n○ Rabies: \n■ Virus that attacks the nervous system and is fatal once symptoms \ndevelop. \n■ Spread through infected animals’ saliva; incubation period in humans is \nabout two months. \n■ Infected animals are known to have behaviors that show no fear and act \nvery agitated.  \n■ Symptoms include fear of water due to pain in the throat, aggressiveness, \nand spasms in the throat. \n○ Dengue & Malaria \n■ Aedes Mosquitoes: \n● Carrier of dengue virus, Zika virus, and yellow fever. \n● Daytime biter, aggressive, still-water breeder. \n■ Anophels Mosquitoes: \n● Carrier of malaria, lymphatic filariasis, and fever. \n● Nighttime biter, spreads fever, crepuscular, breeds in various \nwater sources. \n■ DENGUE VS MALARIA \n● Dengue - high fever, severe headache, nausea & vomiting, muscle \n& joint pain, skin rash, and low platelet count. \n● Malaria - High fever with chills, headache, fatigue, chills & \nsweating. \n○ Malaria stays dormant in the liver for about ten days to four \nweeks. \n○ SIV / HIV / AIDS \n■ SIV: \n● A retrovirus that infects monkeys and apes. \n■ HIV: \n● A virus that attacks the body’s immune system, specifically \ntargeting CD4 white blood cells. \n○ CD4 - acts as the commanders of our immune system; \nthey spot foreign invaders and call CD8 to fight. \n○ CD8 - acts as the soldiers that hunt down and destroy cells \nin the body that have been infected by viruses or have \nbecome cancerous. \n■ AIDS: \n● Most advanced stage of infection caused by HIV. \n● If you are diagnosed with this, it means that your immune system \nis dangerously weak."},{"page":2,"text":"○ Salmonella \n■ A type of bacteria that causes food poisoning, usually meaning that you \nhave an intestinal infection caused by eating undercooked food such as \neggs or chicken. \n■ Symptoms include diarrhea, fever, stomach pains or cramps, nausea and \nvomiting, and headache. \n○ 60% of known infectious diseases are zoonotic. \n○ 75% of emerging infectious diseases originate from wild or domestic animals. \n○ Animal disease causes 70% of global animal production losses. \n \n● Viral Host Specificity \n○ Refers to the tendency or ability of a virus to infect particular host species. \n○ Viruses cannot reproduce independently. \n○ They must enter living cells and use cellular machinery to produce new viral \nparticles. \n1. The virus must attach to a compatible host cell. \n2. The virus must replicate inside the host cell. \n3. The virus must overcome host defenses. \n4. Viral Host Specificity and Zoonotic Spillover. \n○ Viral host specificity helps explain whether an animal-associated virus can \nbiologically infect humans. \n○ However, biological compatibility is only part of the problem. A virus also needs \nan opportunity to encounter a susceptible host. These opportunities may be \ninfluenced by environmental and societal conditions. \n \n● Bacterial Host Specificity \n○ Refers to the tendency or ability of a bacterial species or strain to colonize or \ninfect particular host species. \n○ Viruses require living host cells to reproduce, whereas many bacteria can grow \nand reproduce independently under suitable environmental conditions. \n1. The bacteria must enter or reach a suitable location in the host. \n2. The bacteria must attach to or colonize the host. \n3. The bacteria must survive the host’s defenses. \n○ Viral Host Specificity is strongly influenced by whether a virus can enter and \nreplicate inside host cells. \n○ Bacterial host specificity is influenced by whether bacteria can establish \nthemselves, survive, and sometimes multiply within a particular host."},{"page":3,"text":"HUMAN ACTIVITIES DRIVE ZOONOTIC SPILLOVERS \n \n● Habitat Destruction and Deforestation \n○ Expanding agriculture, logging, and urban development fragment natural \necosystems, forcing wildlife into closer proximity with human settlements and \nlivestock. \n● Intensive Livestock Farming \n○ Rearing large numbers of genetically similar animals in cramped, unsanitary \nconditions creates ideal environments for pathogens to mutate, amplify, and jump \nto farmworkers or nearby communities. \n● Wildlife Trade and Consumption \n○ The capture, transport, and live-market selling of wild animals mix diverse \nspecies that would never naturally meet, drastically increasing the chance of viral \nor bacterial transmission. \n● Climate Change and Global Travel \n○ Rising temperatures expand the geographic ranges of disease vectors (like \nmosquitoes and ticks), while international trade and air travel allow local \noutbreaks to become global crises within hours. \n \nWHAT IS ONE HEALTH? \n \nAn integrated, collaborative approach that recognizes that the health of people, animals, \nplants, and ecosystems is closely linked. By uniting experts in human medicine, veterinary \nscience, ecology, and agriculture, it aims to prevent disease, manage outbreaks, and build \nsustainable environmental policies. \n \n● One Health Approach \n○ Design and implement programs, policies, legislation, and research in which \nmultiple sectors work together to achieve better public health outcomes. \n○ Developed in 2004 \n○ Main Working Organizations: \n■ WHO (World Health Organization) \n■ FAO (Food and Agriculture Organization) \n■ OIE (World Organization for Animal Health) \n■ UNEP (United Nations Environment Programme) \n \n● Health \n○ A state of complete physical, mental, and social well-being and not merely the \nabsence of disease or infirmity. \n \n● Total Wellness \n○ Holistic integration of physical, mental, and spiritual well-being. \n○ Fuels the body, engages the mind, and nurtures the spirit."},{"page":4,"text":"● 8 Dimensions of Wellness \n○ Emotional - coping effectively with life and creating satisfying relationships. \n○ Financial - satisfaction with current and future financial situations. \n○ Social - developing a sense of connection, belonging, and a well-developed \nsupport system. \n○ Spiritual - expanding our sense of purpose and meaning in life. \n○ Occupational - personal satisfaction and enrichment derived from one’s work. \n○ Physical - recognizing the need for physical activity, diet, sleep, and nutrition. \n○ Intellectual - recognizing creative abilities and finding ways to expand knowledge \nand skills. \n○ Environmental - good health by occupying pleasant, stimulating environments \nthat support well-being. \n \nWellbeing, in contrast to states of human health, describes a situation in which people are free \nto choose to do and be what they value. \n \nGOOD HEALTH AND WELLBEING CO-DETERMINE EACH OTHER. \n \nHOWEVER, ATTAINMENT OF OVERALL WELLNESS MAY FACE VARIOUS HEALTH \nHAZARDS. \n \n● Health Hazards \n○ Wellness risks which are usually expressed as probabilties/chances. \n○ Probability of suffering harm from an agent that can cause injury, disease, death, \neconomic loss, or damage. \n1. Chemical hazards - harmful chemicals in air, water, soil, food, and human-made \nproducts. \n2. Natural hazards - such as fire, earthquakes, volcanic eruptions, floods, and storms. \n3. Cultural hazards - such as unsafe working conditions, unsafe highways, criminal assault, \nand poverty. \n4. Lifestyle choices - such as smoking, making poor food choices, drinking too much \nalcohol, and having unsafe sex. \n5. Biological hazards - from more than 1,400 pathogens that can infect humans (a \npathogen is a biological agent that can cause disease in another organism) \na. Bacteria \nb. Viruses \nc. Parasitede \nd. Protozoa \ne. Fungi \n \n● Infectious disease \n○ Pathogen such as a bacterium. A virus or parasite invades the body and \nmultiplies in its cells and tissues. (e.g., Tuberculosis, flu, malaria, measles)"},{"page":5,"text":"● Bacteria \n○ Single-cell organisms that are found everywhere. Most are harmless or \nbeneficial. A bacterial disease results from an infection as the bacteria multiply \nand spread throughout the body. \n○ Can reproduce independently. \n○ Has a cell wall. Its purpose is to prevent bacteria from dying easily and protect \nthem from external conditions. \n○ Alcohol is used to kill bacteria. \n■ Pure alcohol evaporates quickly, which means it may not stay long \nenough to be effective. \n■ A concentration of 65-75% alcohol is effective because it can enter \nbacterial cells while still killing the bacteria. \n● Viruses \n○ Smaller than bacteria and work by invading a cell and taking over its genetic \nmachinery to copy themselves. They then multiply and spread throughout one’s \nbody, causing a viral disease such as flu or AIDS. \n○ Considered as non-living entities; they are essentially chemical entities. \n○ Viruses cannot reproduce independently. They need a host cell to multiply. \n○ Can recognize and target specific cells in the human body. \n○ No cell wall. \n \n● Difference between Bacteria & Viruses \n \nBACTERIA \nVIRUS \nBigger \nSmaller \nLiving \nNon-Living \nFinds Opportunity (sugat) \nRequires a host \nHas cell wall \nNo cell wall \n \n● Difference between Viral & Bacterial Infections \n \nBACTERIAL \nVIRAL \nUsually localized, meaning it stays in \none part of your body, such as the ear \nor throat. \nIt is systemic, meaning it spreads \nthroughout the body. \nIt is SOMETIMES contagious.  \nIt is contagious. \nCan be treated with antibiotics. \nCannot be treated with antibiotics. \nEx. strep throat, pneumonia, urinary \nEx. common colds, flu, chickenpox"},{"page":6,"text":"tract infections. \n \n● How Antibiotic Resistance Occurs \n1. A large population of bacteria is present, containing a small minority of naturally \ndrug-resistant variants. \n2. Antibiotics kill off the pathogenic bacteria causing the illness, but they also \ndestroy beneficial bacteria that normally protect the body. \n3. With competing bacteria eliminated, the surviving resistant bacteria find favorable \nconditions to multiply and dominate the population. \n4. Resistant bacteria can share or transfer their drug-resistance traits to other \nbacterial strains, creating even more difficult clinical challenges. \n \n● Key Causes of Antibiotic Resistance \n○ Over-prescribing of antibiotics by healthcare providers. \n○ Patient non-compliance, such as failing to complete the full course of prescribed \nantibiotics. \n○ Lack of rapid laboratory tests to quickly identify specific pathogens and guide \nappropriate targeted therapy. \n○ Unnecessary use of antibiotics in agriculture (e.g., livestock and farming). \n○ Poor infection control in hospitals and clinics leading to nosocomial spread. \n○ Inadequate hygiene and sanitation practices in communities.  \n \n● How does antibiotic resistance spread? \n○ P2P transmission - resistant bacteria can spread from an infected person to \nanother. \n○ Food - eating contaminated or improperly handled meat can expose people to \nbacteria. \n○ Manure and fertilizers - contaminated manure used in growing vegetables can \nintroduce bacteria into food. \n \n● Transmissible Disease \n○ Infectious bacterial or viral disease that can be transmitted from one person to \nanother.  \n○ Also called communicable diseases. \n○ E.g., influenza, HIV, COVID-19 \n \n● Non-transmissible Disease \n○ Caused by an agent/event other than a living organism and does not spread from \none person to another.  \n○ Non-communicable diseases. \n○ E.g., cardiovascular diseases, most cancers"},{"page":7,"text":"● Ways Infectious Diseases enter the human body \nThey can enter through: \n○ Pets \n○ Livestock \n○ Wild Animals \n○ Insects \n○ Food \n○ Water \n○ Air \n○ Other humans (body fluid) \n \nINFECTIOUS DISEASES ARE STILL MAJOR HEALTH THREATS \n \n-\nInfectious diseases remain serious health threats, especially in less-developed countries. \n-\nSpread through air, water, food, and body fluids. \n-\nA large-scale outbreak of an infectious disease in an area is called an epidemic. \n(LOCAL) \n-\nA global epidemic such as tuberculosis or AIDS is called a pandemic. (GLOBAL) \n \n● Top 10 Global Causes of Death (2000 - 2016) \n○ Ischaemic heart disease (heart’s pipes slowly getting clogged and narrowed) \n○ Stroke \n○ Lower respiratory infections \n○ Chronic obstructive pulmonary disease \n○ Diarrhoeal diseases \n○ Tuberculosis \n○ HIV/AIDS \n○ Preterm birth complications \n○ Trachea, bronchus, lung cancers \n○ Road Injury \n \n● Top 4 Causes of Death in the Philippines (2011 - 2013) \n○ Diseases of the heart, Cerebrovascular diseases (ex., stroke), malignant \nneoplasm (cancer), and Pneumonia. \n \n● SDG 3 GOOD HEALTH AND WELLBEING \n○ Ensuring healthy lives and promoting well-being at all ages is essential to \nsustainable development. Currently, the world is facing a global health crisis \nunlike any other – COVID-19 is spreading human suffering, destabilizing the \nglobal economy, and upending the lives of billions of people around the globe \n(UN, 2020)."},{"page":8,"text":"● COVID-19 (Coronavirus Disease 2019) \n○ Severe acute respiratory syndrome-related coronavirus \n○ The first cases were identified in people with pneumonia in Wuhan, China, in late \nDecember 2019. \n○ Possibilities of animal sources and animal-human transmission were reported \nand scientifically investigated. \n○ Eventually, human-to-human viral transmission occurred. \n○ January 11, 2020 - COVID was still an epidemic. \n○ January 13, 2020 - COVID became a pandemic. \n \n● Comparison of main types of COVID-19 tests \n \nFeature \nRapid Serology \nAntibody Test \nELISA Test \nRT-PCR Test \nSample \nBlood sample (finger \nprick or whole blood) \nBlood sample \nNose / throat swab \nDetects \nCOVID-19 antibodies \n(lgM / lgG) via color \nchange of strip. \nCOVID-19 antibodies \n(lgM / lgG) via \ncolorimetric assay. \nCOVID-19 virus RNA \nvia cDNA \nsequencing. \nMain Advantage \nFast, easy, \nover-the-counter, can \nbe done outside a \nlab, takes several \ndays. \nMore accurate \nantibody detection in \na laboratory setting; \ntakes several days. \nMost accurate test for \nactive infection \n(gold-standard), most \naccurate results early \nin disease \npresentation.  \nMain Limitation \nLess accurate, may \ngive false results, \nrequires rigorous \ntesting of \ncross-reactivity with \nother immune \nresponses. \nRequires rigorous \ntesting of \ncross-reactivity with \nother immune \nresponses; requires a \nlaboratory setting \n(needs a scientist) \nLabor intensive, \nexpensive, requires \nspecialized \nequipment, can lose \naccuracy after ~5 \ndays since symptom \nonset."},{"page":9,"text":"● Dr. Raul Destura \n○ Led the development of a local and quality rRT-PCR Detection Kit \n○ A Thomasian alumnus of College of Science (# omg go uste) \n \n● Coronavirus Group Research (UST) \n○ UST CoV-2 Model - epidemiological model that predicts the future behavior of a \nviral pandemic by examining how it has spread in the past \n○ The epidemiological epicenter of our country is NCR. \n \n● A COVID-19 Timeline \n \nDate \nKey Event \nDecember 2019 \nFirst cases of a new illness reported in \nWuhan, China. \nJanuary 2020  \nCOVID-19 begins spreading to other \ncountries. \nMarch 2020 (March 11 specifically) \nWHO declares COVID-19 a pandemic; \nlockdowns and restrictions begin worldwide. \nMarch 2020 \nCases increase rapidly; hospitals face \nshortages of medical supplies. \nMay - June 2020 \nSome countries ease restrictions, but cases \ncontinue to rise. \nJuly - November 2020 \nMental health and economic challenges \nbecome more evident. \nDecember 2020 \nFirst COVID-19 vaccines are approved. \n2021 \nMass vaccination begins; new variants \nemerge, but cases and deaths gradually \ndecline in many areas."},{"page":10,"text":"● Know the COVID-19 Vaccines \n \nVaccines \nTechnology \nDoses \nMain Advantage \nPfizer-BioNTech \nmRNA \n2 doses \nVery high \neffectiveness \nOxford-AstraZeneca \nViral Vector \n2 doses \nWidely available and \naffordable \nSinovac Corona \nInactivated Virus \n2 doses \nUses traditional \nvaccine technology \nSputnik V \nViral Vector \n2 doses \nHigh reported \neffectiveness \nJanssen \nViral Vector \n1 dose \nSingle-dose vaccine \nBharat BioTech \nInactivated Virus \n2 doses \nTraditional vaccine \ntechnology \nModerna \nmRNA \n2 doses \nHigh effectiveness \nsimilar to Pfizer \nNovavax \nProtein Subunit \n2 doses \nUses protein-based \ntechnology \n \n● What is the best vaccine? \n○ Immediately available (especially if subsidized by the government/company) \n○ Prevents severe condition/symptoms \n○ Prevents hospitalization \n○ Prevents death \n○ ALL the FDA-approved brands guarantee these vaccine functions. \n \nThe pandemic (COVID-19) didn’t just pop up out of nowhere; there were predictions in the past \nthat a virus-type pandemic would emerge. We have been warned both in mainstream media and \non scientific platforms."},{"page":11,"text":"● Pandemics \n \nYear \nOutbreak / Health Event \n1955 \nPolio eradication efforts begin \n1966 \nSmallpox eradication program launched \n1976 \nLegionnaires’ disease identified; Ebola \noutbreak investigated  \n1981 \nHIV / AIDS first reported \n1993 \nE. coli outbreak linked to Jack in the Box \n2001 \nAnthrax attacks in the United States \n2003 \nSARS outbreak \n2014 \nMajor Ebola outbreak \n2015 \nHIV / Hepatitis outbreak related to opioid use \n2016 \nZika virus outbreak \n2019 \nCOVID-19 says hello"}]};

/* StudySpace: zero-dependency, offline-first reviewer.
   Only the bundled STS questions have hand-authored, source-grounded answers.
   User-pasted notes are never misrepresented as AI-generated questions. */
(() => {
  'use strict';
  const STORAGE_KEY = 'studyspace.sts.lq1.v1';
  const MAX_EVENTS = 300;
  const $ = (selector, root = document) => root.querySelector(selector);
  const main = $('#main-content');
  const NAV_LABELS = {dashboard:'Dashboard',lessons:'Lesson reviewer',flashcards:'Flashcards',quiz:'Practice quiz',recall:'Active recall',progress:'My progress'};
  const BASE_IDS = new Set(BUILTIN.lessons.map(x => x.id));
  const DEFAULTS = () => ({version:1, theme:'light', collapsed:false, mastery:{}, completed:[], attempts:[], activities:[], recent:[], recall:{}, customLessons:[]});
  function escapeHTML(value) {
    return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  }
  function isObject(x) {return x && typeof x === 'object' && !Array.isArray(x);}
  function safeArray(x) {return Array.isArray(x) ? x : [];}
  function copyText(x, limit=50000) {return String(x ?? '').slice(0, limit);}
  function clamp(x, low, high) {return Math.min(high, Math.max(low, Number(x) || 0));}
  function pct(x, y) {return y ? Math.round((x / y) * 100) : 0;}
  function humanDate(value) {try {return new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});} catch {return 'Unknown date';}}
  function humanTime(value) {try {return new Date(value).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});} catch {return '';}}
  function pageLabel(lesson) {return lesson?.pages?.length ? `PDF page${lesson.pages.length > 1 ? 's' : ''} ${lesson.pages.join('–')}` : 'Pasted notes';}
  function lessonIdOk(id) {return typeof id === 'string' && (BASE_IDS.has(id) || id.startsWith('custom-'));}
  function sanitizeLesson(raw) {
    if (!isObject(raw) || !String(raw.id || '').startsWith('custom-')) return null;
    const title = copyText(raw.title, 100).trim();
    if (!title) return null;
    const note = copyText(raw.raw, 200000).trim();
    if (!note) return null;
    return makeCustomLesson(copyText(raw.id,100), title, note);
  }
  function normalizeState(raw) {
    const d = DEFAULTS(); if (!isObject(raw)) return d;
    d.theme = raw.theme === 'dark' ? 'dark' : 'light';
    d.collapsed = !!raw.collapsed;
    d.customLessons = safeArray(raw.customLessons).slice(0,30).map(sanitizeLesson).filter(Boolean);
    const validCards = new Set([...BUILTIN.cards, ...d.customLessons.flatMap(l => l.customCards || [])].map(x=>x.id));
    if (isObject(raw.mastery)) for (const [id,value] of Object.entries(raw.mastery)) if (validCards.has(id) && ['mastered','review'].includes(value)) d.mastery[id]=value;
    d.completed = safeArray(raw.completed).filter(lessonIdOk).filter(x => BASE_IDS.has(x) || d.customLessons.some(l=>l.id===x)).slice(0,50);
    d.attempts = safeArray(raw.attempts).filter(x => isObject(x) && Array.isArray(x.ids) && isObject(x.answers)).slice(-60).map(x=>({
      id:copyText(x.id,80), date:copyText(x.date,60), ids:x.ids.filter(id=>BUILTIN.questions.some(q=>q.id===id)),
      answers:Object.fromEntries(Object.entries(x.answers).filter(([k,v])=>typeof k==='string'&&Number.isInteger(v)&&v>=0&&v<4)),
      difficulty:copyText(x.difficulty,30), lesson:copyText(x.lesson,100), total:clamp(x.total,0,100),correct:clamp(x.correct,0,100),
      duration:clamp(x.duration,0,86400), timed:!!x.timed
    }));
    d.activities = safeArray(raw.activities).filter(x=>isObject(x) && typeof x.at==='string').slice(-MAX_EVENTS).map(x=>({type:copyText(x.type,32),at:copyText(x.at,60),lesson:copyText(x.lesson,100)}));
    d.recent = safeArray(raw.recent).filter(x=>typeof x==='string').filter(lessonIdOk).slice(0,15);
    if (isObject(raw.recall)) for (const [id,val] of Object.entries(raw.recall)) if (validCards.has(id) && isObject(val)) d.recall[id]={yes:clamp(val.yes,0,1000),no:clamp(val.no,0,1000)};
    return d;
  }
  function readState() {try {return normalizeState(JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'));} catch {return DEFAULTS();}}
  let data = readState();
  let memoryWarning = false;
  function save() {try {localStorage.setItem(STORAGE_KEY,JSON.stringify(data));memoryWarning=false;return true;} catch {memoryWarning=true; toast('Your browser could not save progress. Check storage permissions.');return false;}}
  function activity(type,lesson='') {
    data.activities.push({at:new Date().toISOString(),type,lesson}); data.activities=data.activities.slice(-MAX_EVENTS);
    save();
  }
  function customId() {return `custom-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;}
  function makeCustomLesson(id,title,raw) {
    const lines = raw.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
    const sections = []; let current = {title:'Your notes',paragraphs:[],bullets:[]};
    const cards=[];
    function push() {if(current.paragraphs.length||current.bullets.length) sections.push(current);}
    lines.forEach(line=>{
      const heading = line.match(/^#{1,4}\s+(.+)$/);
      if (heading) {push(); current={title:heading[1],paragraphs:[],bullets:[]};return;}
      const pair = line.match(/^(.{2,90}?)\s*::\s*(.{3,500})$/);
      if (pair) {
        cards.push({id:`${id}-c${cards.length+1}`,lesson:id,front:pair[2],back:pair[1],detail:'From your pasted term :: definition line.',page:null});
        current.paragraphs.push(`${pair[1]} — ${pair[2]}`); return;
      }
      if (/^[-*•]\s+/.test(line)) current.bullets.push(line.replace(/^[-*•]\s+/,''));
      else current.paragraphs.push(line);
    });
    push();
    if (!sections.length) sections.push({title:'Your notes',paragraphs:[raw.slice(0,5000)]});
    return {id,title,description:'Custom pasted text · stored in this browser',icon:'📝',pages:[],sections,raw,customCards:cards};
  }
  function lessons(){return [...BUILTIN.lessons,...data.customLessons];}
  function cards(){return [...BUILTIN.cards,...data.customLessons.flatMap(x=>x.customCards||[])];}
  function getLesson(id){return lessons().find(x=>x.id===id);}
  function findCard(id){return cards().find(x=>x.id===id);}
  function findQuestion(id){return BUILTIN.questions.find(x=>x.id===id);}
  function shuffle(arr){const result=[...arr];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}if(result.length>1&&result.every((id,i)=>id===arr[i])){const first=result.shift();result.push(first);}return result;}
  function masteryFor(id){return data.mastery[id]||'';}
  function masteryCount(lesson='all'){return cards().filter(c=>lesson==='all'||c.lesson===lesson).filter(c=>masteryFor(c.id)==='mastered').length;}
  function attemptedCards(){return cards().filter(c=>data.mastery[c.id]).length;}
  function finishCount(){return data.completed.length;}
  function lastScore(){const a=data.attempts.at(-1);return a?pct(a.correct,a.total):null;}
  function bar(value,denom){return `<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(value,denom)}"><span style="width:${pct(value,denom)}%"></span></div>`;}
  function pill(label,tone=''){return `<span class="pill ${tone?`pill-${tone}`:''}">${escapeHTML(label)}</span>`;}
  function btn(label,action,attrs='',classes=''){return `<button type="button" class="btn ${classes}" data-action="${escapeHTML(action)}" ${attrs}>${label}</button>`;}
  function heading(eyebrow,title,subtitle,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${subtitle?`<p class="page-subtitle">${subtitle}</p>`:''}</div>${extra?`<div class="button-row">${extra}</div>`:''}</div>`;}
  function noContent(title,desc){return `<div class="card card-pad" style="text-align:center;padding:48px 20px"><div class="empty-icon" aria-hidden="true">✧</div><h2>${escapeHTML(title)}</h2><p class="page-subtitle" style="margin:0 auto">${escapeHTML(desc)}</p></div>`;}
  function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast._timeout);toast._timeout=setTimeout(()=>el.classList.remove('show'),3600);}
  let app = {
    page:'dashboard', lessonId:null, lessonQuery:'', lessonFilter:'all', globalQuery:'',
    flash:{lesson:'all',filter:'all',order:[],index:0,flipped:false,phase:'initial',finished:false},
    recall:{lesson:'all',filter:'all',order:[],index:0,revealed:false},
    quizFilters:{lesson:'all',difficulty:'all',count:20,shuffleAnswers:true,timed:false},
    activeQuiz:null, result:null, timerId:null
  };
  function visitLesson(id){if (!getLesson(id))return;data.recent=[id,...data.recent.filter(x=>x!==id)].slice(0,12);activity('lesson',id);}
  let routeTicket=0,flashTransitionTicket=0,flashBusy=false;
  const prefersLessMotion=()=>window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function renderRoute(){
    const ticket=++routeTicket;
    main.classList.remove('route-enter');
    if(prefersLessMotion()||!main.firstElementChild){main.classList.remove('route-leave');render();return;}
    main.classList.add('route-leave');
    setTimeout(()=>{
      if(ticket!==routeTicket)return;
      main.classList.remove('route-leave');
      render();
      main.classList.add('route-enter');
      setTimeout(()=>{if(ticket===routeTicket)main.classList.remove('route-enter');},380);
    },125);
  }
  function cancelFlashAnimation(){flashTransitionTicket++;flashBusy=false;}
  function animateFlashChange(update){
    if(flashBusy)return;
    flashBusy=true;const ticket=++flashTransitionTicket;
    const card=$('#flip-scene');
    if(!card||prefersLessMotion()){
      flashBusy=false;update();render();return;
    }
    card.classList.add('flash-exit');
    setTimeout(()=>{
      if(ticket!==flashTransitionTicket||app.page!=='flashcards')return;
      flashBusy=false;update();render();
      $('#flip-scene')?.classList.add('flash-enter');
      $('#flash-finished')?.classList.add('flash-enter');
    },130);
  }
  function setFlashFlipped(next){
    const f=app.flash;
    if(flashBusy||f.finished||!$('#flip-scene'))return;
    f.flipped=next;
    const scene=$('#flip-scene');
    scene.classList.toggle('flipped',next);
    scene.setAttribute('aria-pressed',String(next));
    scene.setAttribute('aria-label',next?'Flashcard. Answer shown. Activate to flip back.':'Flashcard. Definition shown. Activate to reveal answer.');
    const button=$('[data-action="flash-flip"]');
    if(button)button.textContent=next?'Show definition ↻':'Reveal answer ↻';
  }
  function go(page,opts={}){
    if (!NAV_LABELS[page])return;
    cancelFlashAnimation();
    if (opts.lesson) app.lessonId=opts.lesson;
    else if (page==='lessons') app.lessonId=null;
    app.page=page;
    if(page==='lessons' && app.lessonId && opts.lesson)visitLesson(opts.lesson);
    if(page==='flashcards')syncFlash();
    if(page==='recall')syncRecall();
    closeModal();closeMobile();renderRoute();
    window.scrollTo({top:0,behavior:'auto'});
  }
  function refreshNav(){
    document.querySelectorAll('.nav-link').forEach(button=>{const on=button.dataset.page===app.page;button.classList.toggle('active',on);if(on)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
    $('#breadcrumb-page').textContent=NAV_LABELS[app.page]||'Dashboard';
    $('#sidebar-library').innerHTML=lessons().map(l=>`<button class="library-item" data-action="open-lesson" data-id="${escapeHTML(l.id)}"><span class="library-dot"></span><span title="${escapeHTML(l.title)}">${escapeHTML(l.title)}</span></button>`).join('');
    document.documentElement.dataset.theme=data.theme;
    document.body.classList.toggle('sidebar-collapsed',data.collapsed);
    $('#theme-label').textContent=data.theme==='dark'?'Light mode':'Dark mode';
    $('#theme-icon').textContent=data.theme==='dark'?'☀':'☾';
  }
  function render(){refreshNav();try{
    main.innerHTML=({dashboard:renderDashboard,lessons:renderLessons,flashcards:renderFlashcards,quiz:renderQuiz,recall:renderRecall,progress:renderProgress})[app.page]();
    if(app.page==='quiz') updateClock();
  } catch(error){console.error(error);main.innerHTML=noContent('Something went wrong','Try reloading the reviewer. Your saved progress is kept locally.');}}
  function lessonRow(l){
    const total=cards().filter(c=>c.lesson===l.id).length, mastered=masteryCount(l.id),done=data.completed.includes(l.id);
    return `<button class="lesson-row" data-action="open-lesson" data-id="${escapeHTML(l.id)}"><span class="lesson-emoji">${l.icon}</span><span class="lesson-info"><strong>${escapeHTML(l.title)}</strong><small>${l.sections.length} topic sections · ${escapeHTML(pageLabel(l))}</small><span class="mini-progress"><span style="width:${pct(mastered,total)}%"></span></span></span><span class="lesson-end">${done?pill('Completed','green'):`<small>${mastered}/${total} cards</small>`}<span aria-hidden="true">→</span></span></button>`;
  }
  function renderDashboard(){
    const master=masteryCount(),all=cards().length,remaining=all-master,total=lessons().length,last=lastScore();
    const recent = data.recent.slice(0,3).map(id=>getLesson(id)).filter(Boolean);
    const scores=data.attempts.slice(-4).reverse();
    return `${heading('WELCOME BACK','Make today a study day.','Your STS Long Quiz 1 reviewer · One Health, infectious diseases, COVID-19 and wellness.',btn('✦ Start reviewing','to-flash','','btn-primary'))}
      <div class="dashboard-hero"><div class="hero-content"><span class="hero-kicker">✧ YOUR STUDY WORKSPACE</span><h1>Small steps. Stronger memory.</h1><p>Review 11 pages of course notes through concise lessons, definition-first flashcards, and practice tests built from your uploaded material.</p><div class="hero-actions">${btn('Explore lessons →','to-lessons','','btn-primary')}${btn('Take a 20-question quiz','to-quiz','','btn-secondary')}</div></div><div class="hero-graphic" aria-hidden="true"><div style="font-size:94px;filter:drop-shadow(0 12px 16px rgba(0,0,0,.2))">📚</div></div></div>
      <div class="stat-grid"><div class="stat-card"><div class="stat-top"><span>Lessons finished</span><span class="stat-icon">✓</span></div><div class="stat-value">${finishCount()}<span style="font-size:16px;color:var(--muted)"> / ${total}</span></div><div class="stat-foot">${pct(finishCount(),total)}% completed</div></div>
      <div class="stat-card"><div class="stat-top"><span>Mastered concepts</span><span class="stat-icon">◫</span></div><div class="stat-value">${master}</div><div class="stat-foot">${remaining} concepts not yet mastered</div></div>
      <div class="stat-card"><div class="stat-top"><span>Quiz attempts</span><span class="stat-icon">☷</span></div><div class="stat-value">${data.attempts.length}</div><div class="stat-foot">${last===null?'No quiz completed yet':`Latest score: ${last}%`}</div></div>
      <div class="stat-card"><div class="stat-top"><span>Review activities</span><span class="stat-icon">✧</span></div><div class="stat-value">${data.activities.length}</div><div class="stat-foot">Recorded on this device</div></div></div>
      <div class="two-cols"><section class="card card-pad"><div class="section-title"><h2>Your lesson library</h2>${btn('See all →','to-lessons','','btn-sm')}</div><div class="lesson-list">${BUILTIN.lessons.slice(0,5).map(lessonRow).join('')}</div></section><section style="display:grid;gap:18px;align-content:start"><div class="card card-pad"><div class="section-title"><h2>Learning snapshot</h2></div><div class="donut-wrap"><div class="donut" style="--value:${pct(master,all)}%"><div class="donut-inner"><strong>${pct(master,all)}%</strong><small>mastered</small></div></div><div style="flex:1"><p style="color:var(--muted);font-size:12px;margin-bottom:8px">${master} of ${all} flashcards mastered</p>${bar(master,all)}<p style="color:var(--muted);font-size:11px;margin:11px 0 0">${attemptedCards()} cards have been marked as mastered or needing review.</p></div></div></div>
        <div class="card card-pad"><div class="section-title"><h2>Recently studied</h2></div>${recent.length?recent.map(l=>`<button class="library-item" data-action="open-lesson" data-id="${escapeHTML(l.id)}"><span style="font-size:20px">${l.icon}</span><span>${escapeHTML(l.title)}</span></button>`).join(''):`<p class="page-subtitle">Open a lesson to see it here.</p>`}<div class="section-title" style="margin:17px 0 10px"><h2>Quiz history</h2></div>${scores.length?scores.map(a=>`<div class="mini-stat"><span>${humanDate(a.date)}</span><strong>${pct(a.correct,a.total)}% · ${a.correct}/${a.total}</strong></div>`).join(''):`<p class="page-subtitle">Your scored attempts appear here.</p>`}</div></section></div>
      <div class="quiz-caution" role="note"><strong>Source accuracy note:</strong> PDF page 8 says COVID-19 became a pandemic on January 13, 2020, while its page 9 timeline says WHO made the declaration on March 11, 2020. The reviewer preserves that inconsistency and labels dated timeline questions explicitly.</div>`;
  }
  function renderLessons(){
    if(app.lessonId)return renderLessonDetail();
    const query=app.lessonQuery.toLowerCase().trim();
    const ls=lessons().filter(l=>!query||`${l.title} ${l.description} ${l.sections.map(s=>s.title+' '+(s.paragraphs||[]).join(' ')+' '+(s.bullets||[]).join(' ')).join(' ')}`.toLowerCase().includes(query));
    return `${heading('YOUR LEARNING MATERIAL','Lesson reviewer','Seven carefully structured lessons cover all 11 pages of the supplied STS notes.',btn('＋ Add your notes','open-add','','btn-primary'))}
      <div class="filter-bar"><div class="search-box"><span class="search-box-icon">⌕</span><input id="lesson-search" class="field" type="search" placeholder="Search lessons and concepts…" aria-label="Search lessons" value="${escapeHTML(app.lessonQuery)}"></div>${pill(`${ls.length} lessons found`,'accent')}</div>
      ${ls.length?`<div class="lesson-grid">${ls.map(l=>{let total=cards().filter(c=>c.lesson===l.id).length,mastered=masteryCount(l.id);return `<button class="lesson-tile" data-action="open-lesson" data-id="${escapeHTML(l.id)}"><div class="tile-head"><span class="tile-emoji">${l.icon}</span>${data.completed.includes(l.id)?pill('Completed','green'):pill(pageLabel(l))}</div><h2>${escapeHTML(l.title)}</h2><p>${escapeHTML(l.description)}</p><div class="tile-foot"><small>${l.sections.length} sections · ${total} flashcards</small><span>→</span></div><div class="mini-progress"><span style="width:${pct(mastered,total)}%"></span></div></button>`}).join('')}</div>`:noContent('No lessons found','Try a different keyword or add your own notes.')}`;
  }
  function sectionHtml(s,index){
    let content=`<section class="reader-section" id="section-${index}"><h2>${index+1}. ${escapeHTML(s.title)}</h2>`;
    if(s.paragraphs)content+=s.paragraphs.map(p=>`<p>${escapeHTML(p)}</p>`).join('');
    if(s.bullets)content+=`<ul>${s.bullets.map(b=>`<li>${escapeHTML(b)}</li>`).join('')}</ul>`;
    if(s.table)content+=`<div class="table-box"><table><thead><tr>${s.table.headers.map(h=>`<th scope="col">${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(r=>`<tr>${r.map(c=>`<td>${escapeHTML(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
    if(s.takeaway)content+=`<div class="quiz-caution" style="border-left-color:var(--accent);background:var(--accent-soft)"><strong>Key takeaway:</strong> ${escapeHTML(s.takeaway)}</div>`;
    if(s.note)content+=`<details><summary>Study note / context</summary><p>${escapeHTML(s.note)}</p></details>`;
    return content+'</section>';
  }
  function renderLessonDetail(){
    const l=getLesson(app.lessonId);if(!l){app.lessonId=null;return renderLessons();}
    const lessonCards=cards().filter(c=>c.lesson===l.id),done=data.completed.includes(l.id);
    const q=BUILTIN.questions.filter(x=>x.lesson===l.id).length;
    const original=BASE_IDS.has(l.id);
    const source=original?BUILTIN.sourcePages.filter(x=>l.pages.includes(x.page)):[];
    return `${heading('LESSON READER',escapeHTML(l.title),`${escapeHTML(pageLabel(l))} · ${l.sections.length} sections`,`${btn('← All lessons','back-lessons')}${!original?btn('Delete custom lesson','delete-custom',`data-id="${escapeHTML(l.id)}"`,'btn-danger'):''}${btn(done?'✓ Completed':'Mark lesson complete','toggle-lesson',`data-id="${escapeHTML(l.id)}"` ,done?'':'btn-primary')}`)}
      <div class="detail-layout"><article class="card reader-card"><div class="reader-head"><div style="font-size:35px">${l.icon}</div><h1>${escapeHTML(l.title)}</h1><p>${escapeHTML(l.description)}</p><div class="chip-row" style="margin-top:14px">${pill(`${lessonCards.length} flashcards`,'accent')}${pill(`${q} source-grounded questions`)}${pill(pageLabel(l))}</div></div>
      ${l.sections.map(sectionHtml).join('')}
      ${original?`<details class="source-raw"><summary>View extracted text from original PDF pages ${l.pages.join(', ')}</summary><p class="source-scope">Original text is included to check the wording of this condensed reviewer.</p>${source.map(p=>`<div class="source-page"><h4>Original PDF page ${p.page}</h4><pre class="original-text">${escapeHTML(p.text)}</pre></div>`).join('')}</details>`:`<details class="source-raw"><summary>View your pasted original notes</summary><pre class="original-text">${escapeHTML(l.raw||'')}</pre></details>`}
      <div class="button-row" style="margin-top:25px">${btn(done?'Mark as incomplete':'✓ Mark as completed','toggle-lesson',`data-id="${escapeHTML(l.id)}"`,'btn-primary')}${btn('Practice these flashcards','lesson-flash',`data-id="${escapeHTML(l.id)}"`)}${q?btn('Quiz on this lesson','lesson-quiz',`data-id="${escapeHTML(l.id)}"`):''}</div></article>
      <aside class="card reader-aside"><h3>In this lesson</h3><div style="display:grid;gap:5px">${l.sections.map((s,i)=>`<button class="toc-link" data-action="jump-section" data-index="${i}">${i+1}. ${escapeHTML(s.title)}</button>`).join('')}</div><div class="divider-line"></div><p class="source-scope">${masteryCount(l.id)} / ${lessonCards.length} concepts mastered</p>${bar(masteryCount(l.id),lessonCards.length)}<div class="mini-stat"><span>Completion</span><strong>${done?'Done':'Not yet'}</strong></div></aside></div>`;
  }
  function filterCards(mode){
    const f=app[mode];return cards().filter(c=>(f.lesson==='all'||c.lesson===f.lesson)&&(f.filter==='all'||(f.filter==='unmastered'?masteryFor(c.id)!=='mastered':masteryFor(c.id)===f.filter)));
  }
  function syncFlash(reset=false){
    const f=app.flash,available=filterCards('flash').map(c=>c.id);
    if(reset){f.order=shuffle(available);f.index=0;f.flipped=false;f.phase='initial';f.finished=false;return;}
    const ids=new Set(available);
    f.order=f.order.filter(id=>ids.has(id));
    for(const id of available)if(!f.order.includes(id))f.order.push(id);
    f.index=clamp(f.index,0,Math.max(0,f.order.length-1));
  }
  function nonMasteredCards(lesson=app.flash.lesson){
    return cards().filter(c=>(lesson==='all'||c.lesson===lesson)&&masteryFor(c.id)!=='mastered');
  }
  function flashRemainingTags(){
    const remaining=nonMasteredCards();
    if(!remaining.length)return '<p class="source-scope">All concepts in this selection are mastered. Great work!</p>';
    return `<div class="remaining-tags" aria-label="Concepts still to master">${remaining.map(c=>`<span class="remaining-tag"><span class="remaining-tag-dot" aria-hidden="true"></span>${escapeHTML(c.back)}</span>`).join('')}</div>`;
  }
  function finishFlashPass(){
    const f=app.flash;
    f.flipped=false;
    if(f.phase==='initial'&&f.filter!=='unmastered'&&f.filter!=='mastered'){
      f.filter='unmastered';
      f.phase='remaining';
      f.order=shuffle(filterCards('flash').map(c=>c.id));
      f.index=0;
      f.finished=f.order.length===0;
      return;
    }
    f.finished=true;
  }
  function advanceFlash(){
    const f=app.flash;
    if(f.finished||!f.order.length)return;
    if(f.index<f.order.length-1){f.index++;f.flipped=false;}
    else finishFlashPass();
  }
  function restartFlash(remaining=false){
    const f=app.flash;
    f.filter=remaining?'unmastered':'all';
    syncFlash(true);
    f.phase=remaining?'remaining':'initial';
    f.finished=!f.order.length&&remaining;
  }
  function syncRecall(reset=false){
    const f=app.recall;const available=filterCards('recall').map(c=>c.id);
    if(reset){f.order=shuffle(available);f.index=0;f.revealed=false;return;}
    f.order=f.order.filter(id=>available.includes(id));for(const id of available)if(!f.order.includes(id))f.order.push(id);
    f.index=clamp(f.index,0,Math.max(0,f.order.length-1));
  }
  function lessonSelect(value,id,includeAll=true){return `<select class="select" id="${id}" aria-label="Choose lesson">${includeAll?'<option value="all">All lessons</option>':''}${lessons().map(l=>`<option value="${escapeHTML(l.id)}" ${value===l.id?'selected':''}>${escapeHTML(l.title)}</option>`).join('')}</select>`;}
  function modeFilter(value,id){return `<select class="select" id="${id}" aria-label="Filter by mastery"><option value="all" ${value==='all'?'selected':''}>All cards</option><option value="unmastered" ${value==='unmastered'?'selected':''}>Not mastered</option><option value="review" ${value==='review'?'selected':''}>Needs review</option><option value="mastered" ${value==='mastered'?'selected':''}>Mastered</option></select>`;}
  function renderFlashcards(){
    syncFlash();
    const f=app.flash,card=f.finished?null:findCard(f.order[f.index]),available=f.order.length;
    const remaining=nonMasteredCards();
    const controls=`${btn('↻ Shuffle','flash-shuffle')}${btn('Reset & shuffle','flash-reset','','btn-primary')}`;
    const intro=heading('MEMORIZE WITH CONFIDENCE','Interactive flashcards','Read the definition first, try to recall the term, then flip to check your answer.',controls);
    const filters=`<div class="filter-bar">${lessonSelect(f.lesson,'flash-lesson')}${modeFilter(f.filter,'flash-filter')}${pill(`${available} cards`,'accent')}${pill(`${masteryCount(f.lesson)} mastered`,'green')}</div>`;
    const hint='<p class="flash-reset-hint">Reset & shuffle restarts the selected lesson’s deck in a new order without clearing mastery.</p>';
    if(f.finished){
      const allDone=remaining.length===0;
      return `${intro}${filters}${hint}<section class="card flash-finished" id="flash-finished" aria-live="polite"><span class="finished-symbol" aria-hidden="true">${allDone?'✦':'◫'}</span><p class="eyebrow">REVIEW SESSION COMPLETE</p><h2>${allDone?'All concepts mastered!':'Here’s what still needs practice'}</h2><p>${allDone?'You have mastered every concept in this lesson selection.':'These are the non-mastered terms. Your progress is saved, and you can study them again in a freshly shuffled order.'}</p><div class="remaining-summary"><strong>${remaining.length} concepts remaining</strong>${flashRemainingTags()}</div><div class="button-row" style="justify-content:center">${remaining.length?btn('Review remaining cards →','flash-review-again','','btn-primary'):''}${btn('↻ Reset & shuffle all','flash-reset')}</div></section>`;
    }
    const followup=f.phase==='remaining'?`<section class="remaining-banner" aria-live="polite"><div><p class="eyebrow">FOCUSED FOLLOW-UP</p><h2>${remaining.length} non-mastered concepts left</h2><p>The first pass is complete. Only cards you have not mastered appear now.</p></div>${flashRemainingTags()}</section>`:'';
    const body=!card?noContent('No matching flashcards','Choose All cards or another lesson, or add Term :: Definition pairs to your notes.'):`<div class="study-layout"><div><div class="flash-subhead"><span>Card <strong>${f.index+1}</strong> of ${available}</span><span>${escapeHTML(getLesson(card.lesson)?.title||'Your notes')} · ${card.page?`PDF p. ${card.page}`:'Pasted notes'}</span></div>
      <div class="flip-scene ${f.flipped?'flipped':''}" id="flip-scene" role="button" tabindex="0" aria-label="Flashcard. ${f.flipped?'Answer shown. Activate to flip back.':'Definition shown. Activate to reveal answer.'}" aria-pressed="${f.flipped}">
      <div class="flip-card"><div class="flip-face front"><div class="flip-face-label">FRONT · DEFINITION</div><div class="flash-text">${escapeHTML(card.front)}</div><p class="flash-hint">Click or press Space to reveal the term ↻</p></div><div class="flip-face back"><div class="flip-face-label">BACK · TERM / ANSWER</div><div class="flash-text">${escapeHTML(card.back)}</div><p class="flash-hint">${escapeHTML(card.detail||'')}</p></div></div></div>
      <div class="flash-controls">${btn('← Previous','flash-prev',f.index===0?'disabled':'')}${btn(f.flipped?'Show definition ↻':'Reveal answer ↻','flash-flip','','btn-primary')}${btn(f.index>=available-1?'Finish pass →':'Next →','flash-next')}</div>
      <div class="flash-status-btns">${btn('↻ Needs review','flash-mark',`data-value="review" data-id="${escapeHTML(card.id)}"`,masteryFor(card.id)==='review'?'btn-muted':'')}${btn('✓ Mastered','flash-mark',`data-value="mastered" data-id="${escapeHTML(card.id)}"`,masteryFor(card.id)==='mastered'?'btn-primary':'')}</div></div>
      <aside class="card flash-sidebar"><h3>Learning progress</h3><div class="mini-stat"><span>Mastered</span><strong>${masteryCount(f.lesson)}</strong></div><div class="mini-stat"><span>Needs review</span><strong>${cards().filter(c=>(f.lesson==='all'||c.lesson===f.lesson)&&masteryFor(c.id)==='review').length}</strong></div><div class="mini-stat"><span>Unmarked</span><strong>${cards().filter(c=>(f.lesson==='all'||c.lesson===f.lesson)&&!masteryFor(c.id)).length}</strong></div>${bar(masteryCount(f.lesson),cards().filter(c=>f.lesson==='all'||c.lesson===f.lesson).length)}<div class="divider-line"></div><p class="source-scope">Keyboard shortcuts</p><div class="mini-stat"><span>Previous / Next</span><strong>← / →</strong></div><div class="mini-stat"><span>Flip card</span><strong>Space</strong></div><div class="divider-line"></div>${pill(masteryFor(card.id)==='mastered'?'✓ Mastered':masteryFor(card.id)==='review'?'Needs review':'Not yet rated',masteryFor(card.id)==='mastered'?'green':masteryFor(card.id)==='review'?'orange':'')}</aside></div>`;
    return `${intro}${filters}${hint}${followup}${body}`;
  }
  function renderRecall(){
    syncRecall();const f=app.recall,card=findCard(f.order[f.index]);
    return `${heading('TEST YOUR MEMORY','Active recall','Think of the answer before you reveal it. Rate whether you recalled it correctly.',btn('↻ New random order','recall-shuffle','','btn-primary'))}
      <div class="filter-bar">${lessonSelect(f.lesson,'recall-lesson')}${modeFilter(f.filter,'recall-filter')}${pill(`${f.order.length} prompts`,'accent')}</div>
      ${!card?noContent('No prompts in this filter','Choose All cards to restart your recall session.'):`<div class="card card-pad" style="max-width:870px;margin:0 auto"><div class="flash-subhead"><span>Prompt ${f.index+1} / ${f.order.length}</span><span>${escapeHTML(getLesson(card.lesson)?.title||'Pasted notes')}</span></div><div class="recall-front"><div class="recall-question">${escapeHTML(card.front)}</div>${f.revealed?`<div class="recall-answer">${escapeHTML(card.back)}<small>${escapeHTML(card.detail||'')}</small></div>`:''}</div>
      <div class="recall-actions">${f.revealed?`${btn('Not yet — review again','recall-rate',`data-value="no" data-id="${escapeHTML(card.id)}"`)}${btn('I remembered it!','recall-rate',`data-value="yes" data-id="${escapeHTML(card.id)}"`,'btn-primary')}`:btn('Reveal answer','recall-reveal','','btn-primary')}</div><div class="flash-controls"><span class="source-scope">${card.page?`From PDF page ${card.page}`:'From your pasted notes'} · Attempts: ${(data.recall[card.id]?.yes||0)+(data.recall[card.id]?.no||0)}</span><div class="button-row">${btn('← Previous','recall-prev',f.index===0?'disabled':'')}${btn('Skip →','recall-next',f.index>=f.order.length-1?'disabled':'')}</div></div></div>`}`;
  }
  function quizPool() {
    const f=app.quizFilters;
    return BUILTIN.questions.filter(q=>(f.lesson==='all'||q.lesson===f.lesson)&&(f.difficulty==='all'||q.difficulty===f.difficulty));
  }
  function renderQuizSetup(){
    const f=app.quizFilters,pool=quizPool(),available=pool.length;
    return `${heading('PRACTICE MAKES PROGRESS','Knowledge check','20 multiple-choice questions by default · Four choices each · Answers appear only after submission.')}
    <div class="quiz-setup card card-pad" style="max-width:890px"><div class="section-title"><h2>Customize your practice quiz</h2>${pill(`${available} available questions`,'accent')}</div>
      <div class="setting-row"><label class="form-label">Subject / lesson${lessonSelect(f.lesson,'quiz-lesson')}</label><label class="form-label">Difficulty<select class="select" id="quiz-difficulty" aria-label="Quiz difficulty"><option value="all" ${f.difficulty==='all'?'selected':''}>Mixed difficulty</option>${['Easy','Moderate','Difficult'].map(x=>`<option value="${x}" ${f.difficulty===x?'selected':''}>${x}</option>`).join('')}</select></label></div>
      <div class="setting-row"><label class="form-label">Question count<select id="quiz-count" class="select" aria-label="Number of quiz questions">${[10,20,30,50].map(n=>`<option value="${n}" ${f.count===n?'selected':''}>${n} questions</option>`).join('')}<option value="all" ${f.count==='all'?'selected':''}>All available (${available})</option></select></label><div class="form-label">Available levels<div class="chip-row" style="margin-top:12px">${['Easy','Moderate','Difficult'].map(lvl=>pill(`${lvl}: ${pool.filter(q=>q.difficulty===lvl).length}`)).join('')}</div></div></div>
      <div style="display:grid;gap:12px;margin:17px 0"><label class="check-line"><input type="checkbox" id="quiz-shuffle" ${f.shuffleAnswers?'checked':''}><span><strong>Shuffle answer choices</strong><small>The position of the correct answer changes each attempt.</small></span></label><label class="check-line"><input type="checkbox" id="quiz-timed" ${f.timed?'checked':''}><span><strong>Timed challenge</strong><small>1 minute per question. The quiz submits when time runs out.</small></span></label></div>
      <div class="quiz-caution">${available?`This selection contains ${available} unique questions. Starting a ${f.count==='all'?'full':f.count+'-question'} quiz will use ${f.count==='all'?available:Math.min(available,Number(f.count))} questions, with no duplicates.`:'No questions match this selection. Choose another difficulty or lesson.'} Custom pasted notes do not generate multiple-choice questions automatically.</div>
      ${btn('Start practice quiz →','quiz-start',available?'':'disabled','btn-primary')}
      ${data.attempts.length?`<div class="divider-line"></div><h3>Previous attempts</h3><div class="table-box"><table class="history-table"><thead><tr><th>Date</th><th>Score</th><th>Scope</th><th></th></tr></thead><tbody>${data.attempts.slice(-5).reverse().map(a=>`<tr><td>${humanDate(a.date)} ${humanTime(a.date)}</td><td><strong>${a.correct}/${a.total}</strong> (${pct(a.correct,a.total)}%)</td><td>${escapeHTML(a.difficulty==='all'?'Mixed':a.difficulty)}</td><td>${btn('Review','review-attempt',`data-id="${escapeHTML(a.id)}"`,'btn-sm')}</td></tr>`).join('')}</tbody></table></div>`:''}</div>`;
  }
  function quizQuestion(session){return findQuestion(session.ids[session.current]);}
  function renderActiveQuiz(){
    const s=app.activeQuiz;if(!s)return renderQuizSetup();
    const q=quizQuestion(s);if(!q){app.activeQuiz=null;return renderQuizSetup();}
    const chosen=s.answers[q.id];const answered=s.ids.filter(id=>Number.isInteger(s.answers[id])).length;
    return `${heading('PRACTICE QUIZ','Focus on what you know','Your answers are saved only when you submit the quiz.',btn('Exit quiz','quiz-exit','','btn-danger'))}
      <div class="quiz-head"><span>${answered} of ${s.ids.length} answered</span><strong id="quiz-clock" aria-live="off">${s.timed?'Time remaining: —':'Untimed session'}</strong></div>${bar(answered,s.ids.length)}
      <div class="quiz-grid"><div><section class="card quiz-question-card"><div class="question-kicker"><span>QUESTION ${s.current+1} OF ${s.ids.length}</span><span>${escapeHTML(q.difficulty)} · ${escapeHTML(getLesson(q.lesson)?.title||'STS')}</span></div><h2>${escapeHTML(q.prompt)}</h2><div class="choices" role="group" aria-label="Answer choices">${s.choiceOrders[q.id].map((originalIdx,index)=>`<button class="choice ${chosen===originalIdx?'selected':''}" data-action="quiz-choice" data-value="${originalIdx}" aria-pressed="${chosen===originalIdx}"><span class="choice-index">${'ABCD'[index]}</span><span>${escapeHTML(q.choices[originalIdx])}</span></button>`).join('')}</div><div class="quiz-controls">${btn('← Previous','quiz-prev',s.current===0?'disabled':'')}${btn(s.current===s.ids.length-1?'Review answers →':'Next question →','quiz-next',s.current===s.ids.length-1?'disabled':'','btn-primary')}</div></section><p class="source-scope" style="margin:15px 1px">Correct answers and explanations remain hidden until the quiz is submitted.</p></div>
      <aside class="card question-panel"><h3>Question navigator</h3><p>Jump to any question · Filled = answered</p><div class="question-dots">${s.ids.map((id,i)=>`<button class="question-dot ${Number.isInteger(s.answers[id])?'answered':''} ${s.current===i?'current':''}" data-action="quiz-jump" data-index="${i}" aria-label="Go to question ${i+1}, ${Number.isInteger(s.answers[id])?'answered':'unanswered'}" aria-current="${s.current===i?'step':'false'}">${i+1}</button>`).join('')}</div><div class="mini-stat"><span>Answered</span><strong>${answered}</strong></div><div class="mini-stat"><span>Remaining</span><strong>${s.ids.length-answered}</strong></div>${btn('Submit quiz','quiz-submit','','btn-primary quiz-submit')}</aside></div>`;
  }
  function renderQuizResults(attempt){
    const ids=attempt.ids||[],correct=ids.filter(id=>{let q=findQuestion(id);return q && attempt.answers[id]===q.answer;}).length;
    const total=ids.length,wrong=total-correct;
    const grouping=new Map();
    ids.forEach(id=>{const q=findQuestion(id);if(!q)return;const old=grouping.get(q.lesson)||{correct:0,total:0};old.total++;if(attempt.answers[id]===q.answer)old.correct++;grouping.set(q.lesson,old);});
    const weak=[...grouping].filter(([,v])=>v.correct<v.total).sort((a,b)=>pct(a[1].correct,a[1].total)-pct(b[1].correct,b[1].total));
    return `${heading('YOUR QUIZ RESULTS','Review your answers','Answers and source-based explanations are now available.',`${btn('New quiz','quiz-new')}${btn('Retake with new order','quiz-start','','btn-primary')}`)}
      <div class="score-hero"><p class="eyebrow">SESSION COMPLETE</p><h1>${pct(correct,total)>=85?'Excellent work!':pct(correct,total)>=60?'Keep building on this.':'Every mistake is a chance to learn.'}</h1><div class="score-bubble"><div><strong>${pct(correct,total)}%</strong><small>your score</small></div></div><div class="score-stats"><span><strong>${correct}</strong> Correct</span><span><strong>${wrong}</strong> Incorrect / unanswered</span><span><strong>${total}</strong> Questions</span><span><strong>${Math.floor((attempt.duration||0)/60)}m ${(attempt.duration||0)%60}s</strong> Study time</span></div><div class="button-row" style="justify-content:center">${btn('Review questions ↓','scroll-results','','btn-primary')}${btn('Back to dashboard','to-dashboard')}</div></div>
      <div class="card card-pad results-weak"><div class="section-title"><h2>Topic breakdown</h2>${pill(`${weak.length} topics to revisit`,'orange')}</div>${[...grouping].map(([id,counts])=>`<div class="collection-bar"><strong>${escapeHTML(getLesson(id)?.title||id)}</strong>${bar(counts.correct,counts.total)}<small>${counts.correct}/${counts.total}</small></div>`).join('')}${weak.length?`<p class="source-scope">Focus next on ${escapeHTML(getLesson(weak[0][0])?.title||'your weakest topic')}; this was your lowest-scoring lesson in this attempt.</p>`:'<p class="source-scope">All attempted topics were answered correctly!</p>'}</div>
      <div id="result-answers" class="result-list"><h2>Question-by-question review</h2>${ids.map((id,i)=>{const q=findQuestion(id);if(!q)return '';const chosen=attempt.answers[id],ok=chosen===q.answer;return `<article class="result-item"><div class="result-header"><span class="review-label">QUESTION ${i+1} · ${escapeHTML(getLesson(q.lesson)?.title||'STS')} · ${escapeHTML(q.difficulty)} · PDF P. ${q.page}</span>${pill(ok?'Correct':'Incorrect',ok?'green':'orange')}</div><h3>${escapeHTML(q.prompt)}</h3><p class="${ok?'correct':'incorrect'}">Your answer: ${Number.isInteger(chosen)?escapeHTML(q.choices[chosen]):'Unanswered'}</p>${!ok?`<p class="correct"><strong>Correct:</strong> ${escapeHTML(q.choices[q.answer])}</p>`:''}<p style="margin-top:11px;color:var(--muted)"><strong>Explanation:</strong> ${escapeHTML(q.explanation)}</p></article>`;}).join('')}</div>`;
  }
  function renderQuiz(){if(app.result)return renderQuizResults(app.result);if(app.activeQuiz)return renderActiveQuiz();return renderQuizSetup();}
  function startQuiz(){
    const pool=quizPool();if(!pool.length){toast('No questions available. Change the quiz filters.');return;}
    const chosen=shuffle(pool).slice(0,app.quizFilters.count==='all'?pool.length:Math.min(Number(app.quizFilters.count)||20,pool.length));
    const choiceOrders={};chosen.forEach(q=>choiceOrders[q.id]=app.quizFilters.shuffleAnswers?shuffle([0,1,2,3]):[0,1,2,3]);
    const start=Date.now(),timed=app.quizFilters.timed;
    app.activeQuiz={ids:chosen.map(q=>q.id),answers:{},choiceOrders,current:0,startedAt:start,endsAt:timed?start+chosen.length*60000:null,timed,difficulty:app.quizFilters.difficulty,lesson:app.quizFilters.lesson};
    app.result=null;
    clearInterval(app.timerId);
    if(timed)app.timerId=setInterval(()=>{const s=app.activeQuiz;if(!s){clearInterval(app.timerId);return;}if(Date.now()>=s.endsAt)finishQuiz(true);else updateClock();},500);
    activity('quiz-start',app.quizFilters.lesson);render();
  }
  function updateClock(){const el=$('#quiz-clock');const s=app.activeQuiz;if(!el||!s)return;if(!s.timed){el.textContent='Untimed session';return;}const sec=Math.max(0,Math.ceil((s.endsAt-Date.now())/1000));el.textContent=`Time remaining: ${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;}
  function finishQuiz(expired=false){
    const s=app.activeQuiz;if(!s)return;
    if(!expired&&s.ids.some(id=>!Number.isInteger(s.answers[id]))&&!confirm('You have unanswered questions. Submit the quiz anyway?'))return;
    clearInterval(app.timerId);app.timerId=null;
    const attempt={id:`attempt-${Date.now()}-${Math.floor(Math.random()*10000)}`,date:new Date().toISOString(),ids:[...s.ids],answers:{...s.answers},lesson:s.lesson,difficulty:s.difficulty,total:s.ids.length,correct:s.ids.reduce((n,id)=>n+(s.answers[id]===findQuestion(id)?.answer?1:0),0),timed:s.timed,duration:Math.max(0,Math.round((Date.now()-s.startedAt)/1000))};
    data.attempts.push(attempt);data.attempts=data.attempts.slice(-60);app.result=attempt;app.activeQuiz=null;
    activity('quiz',s.lesson);render();window.scrollTo({top:0});if(expired)toast('Time expired. Your quiz was submitted automatically.');
  }
  function renderProgress(){
    const all=cards(),mastered=masteryCount(),review=all.filter(c=>masteryFor(c.id)==='review').length,unused=all.length-mastered-review;
    const remembered=Object.values(data.recall).reduce((a,x)=>a+(x.yes||0),0),missed=Object.values(data.recall).reduce((a,x)=>a+(x.no||0),0);
    const attempts=data.attempts,avg=attempts.length?Math.round(attempts.reduce((n,a)=>n+pct(a.correct,a.total),0)/attempts.length):null;
    const dates=new Set(data.activities.map(e=>e.at.slice(0,10)));
    return `${heading('KEEP IMPROVING','My study progress','All data is stored in your browser on this device; no account or server is required.',btn('Export progress JSON','export','','btn-primary'))}
      <div class="stat-grid"><div class="stat-card"><div class="stat-top">Card mastery <span class="stat-icon">◫</span></div><div class="stat-value">${pct(mastered,all.length)}%</div><div class="stat-foot">${mastered} of ${all.length} concepts</div></div><div class="stat-card"><div class="stat-top">Lesson completion <span class="stat-icon">✓</span></div><div class="stat-value">${pct(finishCount(),lessons().length)}%</div><div class="stat-foot">${finishCount()} of ${lessons().length} completed</div></div><div class="stat-card"><div class="stat-top">Average quiz score <span class="stat-icon">☷</span></div><div class="stat-value">${avg===null?'—':avg+'%'}</div><div class="stat-foot">From ${attempts.length} attempts</div></div><div class="stat-card"><div class="stat-top">Active study days <span class="stat-icon">✧</span></div><div class="stat-value">${dates.size}</div><div class="stat-foot">${data.activities.length} recorded study actions</div></div></div>
      <div class="progress-grid"><section class="card card-pad"><h2>Flashcard mastery</h2><div class="donut-wrap"><div class="donut" style="--value:${pct(mastered,all.length)}%"><div class="donut-inner"><strong>${pct(mastered,all.length)}%</strong><small>mastered</small></div></div><div style="flex:1"><div class="mini-stat"><span>✓ Mastered</span><strong>${mastered}</strong></div><div class="mini-stat"><span>↻ Needs review</span><strong>${review}</strong></div><div class="mini-stat"><span>Not attempted</span><strong>${unused}</strong></div></div></div><div class="divider-line"></div><h3>By lesson</h3>${lessons().map(l=>{const count=all.filter(c=>c.lesson===l.id).length;return `<div class="collection-bar"><strong>${escapeHTML(l.title)}</strong>${bar(masteryCount(l.id),count)}<small>${masteryCount(l.id)}/${count}</small></div>`;}).join('')}</section>
      <section class="card card-pad"><h2>Active recall</h2><p class="page-subtitle">Self-assessment counts from your revealed prompts.</p><div class="mini-stat"><span>Remembered correctly</span><strong>${remembered}</strong></div><div class="mini-stat"><span>Needs another review</span><strong>${missed}</strong></div>${bar(remembered,remembered+missed)}<div class="divider-line"></div><h2>Completed lessons</h2>${lessons().map(l=>`<div class="mini-stat"><span>${escapeHTML(l.title)}</span>${data.completed.includes(l.id)?pill('Completed','green'):pill('Not finished')}</div>`).join('')}</section></div>
      <section class="card card-pad progress-section"><div class="section-title"><h2>Quiz attempt history</h2>${btn('Practice again','to-quiz','','btn-sm')}</div>${attempts.length?`<div class="table-box"><table class="history-table"><thead><tr><th>Date</th><th>Questions</th><th>Score</th><th>Difficulty</th><th>Review</th></tr></thead><tbody>${attempts.slice().reverse().map(a=>`<tr><td>${humanDate(a.date)} ${humanTime(a.date)}</td><td>${a.total}</td><td><strong>${a.correct}/${a.total} · ${pct(a.correct,a.total)}%</strong></td><td>${escapeHTML(a.difficulty==='all'?'Mixed':a.difficulty)}</td><td>${btn('View explanations','review-attempt',`data-id="${escapeHTML(a.id)}"`,'btn-sm')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="page-subtitle">Finish a quiz to start your score history.</p>'}</section>
      <section class="card settings-card progress-section"><div class="section-title"><h2>Your data & preferences</h2></div><p>Export a backup, restore a saved JSON file, or erase progress. Your source reviewer is always retained.</p><div class="settings-buttons">${btn('↓ Export JSON','export')}${btn('↑ Import JSON','import')}${btn('Reset saved progress','reset','','btn-danger')}</div>${memoryWarning?'<p class="error-text">The browser did not allow the latest save.</p>':''}<div class="divider-line"></div><p class="source-scope">Pasted lessons are saved only in this browser. For reliable access, save the application files together and keep JSON backups.</p></section>`;
  }
  function closeMobile(){$('#sidebar').classList.remove('mobile-open');$('#scrim').hidden=true;}
  function openMobile(){$('#sidebar').classList.add('mobile-open');$('#scrim').hidden=false;}
  function closeModal(){$('#modal-layer').hidden=true;$('#modal-content').innerHTML='';}
  function openModal(body){$('#modal-content').innerHTML=body;$('#modal-layer').hidden=false;const input=$('#modal-content input:not([type=checkbox]),#modal-content textarea');if(input)setTimeout(()=>input.focus(),0);}
  function openAddNotes(){
    openModal(`<div class="modal-head"><div><h2 id="modal-title">Add pasted notes</h2><p>Add a searchable lesson. No artificial intelligence or file parsing is involved.</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div>
      <form id="notes-form"><label class="form-label">Lesson title<input required id="notes-title" class="field" maxlength="100" placeholder="e.g., STS Lesson 2" autocomplete="off"></label><label class="form-label">Study notes<textarea required id="notes-text" class="textarea" rows="12" placeholder="# Heading\nExplain the concept in your own material.\n- Main point\n\nZoonosis :: Infection transmitted between animals and humans"></textarea></label>
      <div class="quiz-caution">Use <strong># Heading</strong> for sections, <strong>- point</strong> for bullets, and <strong>Term :: Definition</strong> on its own line to create a flashcard (definition on the front). We do not automatically invent quiz questions from pasted notes.</div><div class="modal-foot">${btn('Cancel','close-modal')}<button class="btn btn-primary" type="submit">Save lesson</button></div></form>`);
  }
  function searchableItems(query){
    const q=query.toLowerCase().trim();if(!q)return [];
    const results=[];
    for(const l of lessons()){
      if(l.title.toLowerCase().includes(q)||l.description.toLowerCase().includes(q)) results.push({lesson:l,section:null,title:l.title,preview:l.description});
      for(const sec of l.sections){const txt=[sec.title,...(sec.paragraphs||[]),...(sec.bullets||[]),...(sec.table?.rows||[]).flat()].join(' ');
        if(txt.toLowerCase().includes(q))results.push({lesson:l,section:sec.title,title:sec.title,preview:txt.slice(Math.max(0,txt.toLowerCase().indexOf(q)-65),txt.toLowerCase().indexOf(q)+140)});
      }
    }
    return results.slice(0,30);
  }
  function openSearch(){openModal(`<div class="modal-head"><div><h2 id="modal-title">Search concepts</h2><p>Search all source-backed lesson sections and your pasted notes.</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close">✕</button></div><div class="search-box"><span class="search-box-icon">⌕</span><input id="global-query" class="field" type="search" aria-label="Search study concepts" placeholder="Try antibiotic resistance or CD4…" value="${escapeHTML(app.globalQuery)}"></div><div id="global-results" class="search-results"></div>`);refreshSearch();}
  function refreshSearch(){const target=$('#global-results');if(!target)return;const results=searchableItems(app.globalQuery);target.innerHTML=results.length?results.map(r=>`<button class="search-result" data-action="open-search-result" data-id="${escapeHTML(r.lesson.id)}" data-section="${escapeHTML(r.section||'')}"><strong>${escapeHTML(r.title)}</strong><small>${escapeHTML(r.lesson.title)} · ${escapeHTML(pageLabel(r.lesson))}</small><span style="font-size:11px;color:var(--muted)">${escapeHTML(r.preview)}</span></button>`).join(''):app.globalQuery?'<p class="source-scope">No matching concepts. Try a broader keyword.</p>':'<p class="source-scope">Start typing to search lessons and terminology.</p>';}
  function exportData(){
    const payload={app:'StudySpace STS Reviewer',version:1,exportedAt:new Date().toISOString(),state:data};
    const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);
    const a=document.createElement('a');a.href=url;a.download=`sts-studyspace-progress-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);
    toast('Progress exported as JSON.');
  }
  function importData(file){if(!file)return;if(file.size>5_000_000){toast('Choose a JSON file under 5 MB.');return;}
    const reader=new FileReader();reader.onerror=()=>toast('Unable to read file.');reader.onload=()=>{
      try {const payload=JSON.parse(String(reader.result));if(!isObject(payload)||payload.app!=='StudySpace STS Reviewer'||!isObject(payload.state))throw Error('Not a StudySpace progress export.');
        if(!confirm('Import this backup? It will replace progress and pasted notes saved in this browser.'))return;
        data=normalizeState(payload.state);save();app.lessonId=null;app.result=null;app.activeQuiz=null;clearInterval(app.timerId);app.flash.order=[];app.recall.order=[];go('progress');toast('Study progress imported.');
      } catch(err){toast(`Import failed: ${err.message}`);} };reader.readAsText(file);
  }
  function resetData(){if(!confirm('Reset all lesson completion, flashcard mastery, quiz results, and pasted lessons on this browser? This cannot be undone unless you exported a backup.'))return;
    const theme=data.theme,collapsed=data.collapsed;data=DEFAULTS();data.theme=theme;data.collapsed=collapsed;save();app.lessonId=null;app.flash={lesson:'all',filter:'all',order:[],index:0,flipped:false,phase:'initial',finished:false};app.recall={lesson:'all',filter:'all',order:[],index:0,revealed:false};app.activeQuiz=null;app.result=null;clearInterval(app.timerId);go('dashboard');toast('Saved study progress reset.');
  }
  function markFlash(id,value){
    const f=app.flash,c=findCard(id);
    if(!c||f.finished||f.order[f.index]!==id||!['mastered','review'].includes(value))return;
    animateFlashChange(()=>{
      const oldOrder=[...f.order],oldIndex=f.index;
      data.mastery[id]=value;
      activity('flashcard',c.lesson);
      f.flipped=false;
      syncFlash();
      const nextId=oldOrder.slice(oldIndex+1).find(next=>f.order.includes(next));
      if(nextId)f.index=f.order.indexOf(nextId);
      else finishFlashPass();
      toast(value==='mastered'?'Mastered! Moving to the next card.':'Saved for review. Moving on.');
    });
  }
  function rateRecall(id,value){const c=findCard(id);if(!c)return;const stats=data.recall[id]||{yes:0,no:0};stats[value]=Math.min(1000,(stats[value]||0)+1);data.recall[id]=stats;
    data.mastery[id]=value==='yes'?'mastered':'review';activity('recall',c.lesson);app.recall.revealed=false;
    const wasInOrder=app.recall.order.includes(id);syncRecall();if(app.recall.order.length)app.recall.index=Math.min(app.recall.index+(wasInOrder&&app.recall.order.includes(id)?1:0),app.recall.order.length-1);
    render();toast(value==='yes'?'Great recall — card marked mastered.':'Card queued for another review.');
  }
  function setTheme(){data.theme=data.theme==='dark'?'light':'dark';save();render();}
  function deleteCustomLesson(id){const l=data.customLessons.find(l=>l.id===id);if(!l)return;if(!confirm(`Remove your custom lesson “${l.title}” and its flashcards?`))return;
    data.customLessons=data.customLessons.filter(l=>l.id!==id);data.recent=data.recent.filter(x=>x!==id);data.completed=data.completed.filter(x=>x!==id);save();app.lessonId=null;go('lessons');toast('Custom lesson removed.');
  }
  function onAction(action,el){
    const id=el.dataset.id,val=el.dataset.value,idx=Number(el.dataset.index);
    switch(action){
      case 'to-dashboard':go('dashboard');break;case 'to-lessons':app.lessonId=null;go('lessons');break;
      case 'to-flash':go('flashcards');break;case 'to-quiz':go('quiz');break;
      case 'open-lesson':go('lessons',{lesson:id});break;
      case 'back-lessons':app.lessonId=null;go('lessons');break;
      case 'toggle-lesson': {const l=getLesson(id);if(!l)return;data.completed=data.completed.includes(id)?data.completed.filter(x=>x!==id):[...data.completed,id];activity('lesson-completed',id);render();toast(data.completed.includes(id)?'Lesson marked complete.':'Lesson marked incomplete.');break;}
      case 'lesson-flash':app.flash.lesson=id;app.flash.filter='all';syncFlash(true);go('flashcards');break;
      case 'lesson-quiz':app.quizFilters.lesson=id;app.quizFilters.difficulty='all';app.result=null;go('quiz');break;
      case 'jump-section':$('#section-'+idx)?.scrollIntoView({behavior:'smooth',block:'start'});break;
      case 'flash-prev':if(app.flash.index>0&&!app.flash.finished)animateFlashChange(()=>{app.flash.index--;app.flash.flipped=false;});break;
      case 'flash-next':if(!app.flash.finished&&app.flash.order.length)animateFlashChange(advanceFlash);break;
      case 'flash-flip':setFlashFlipped(!app.flash.flipped);break;
      case 'flash-mark':markFlash(id,val);break;
      case 'flash-shuffle':cancelFlashAnimation();app.flash.order=shuffle(app.flash.order);app.flash.index=0;app.flash.flipped=false;app.flash.finished=false;render();toast('Flashcard order shuffled.');break;
      case 'flash-reset':cancelFlashAnimation();restartFlash(false);render();toast('Deck reset and shuffled. Mastery is preserved.');break;
      case 'flash-review-again':cancelFlashAnimation();restartFlash(true);render();toast('Reviewing non-mastered concepts in a new order.');break;
      case 'recall-prev':app.recall.index=Math.max(0,app.recall.index-1);app.recall.revealed=false;render();break;
      case 'recall-next':app.recall.index=Math.min(app.recall.order.length-1,app.recall.index+1);app.recall.revealed=false;render();break;
      case 'recall-shuffle':app.recall.order=shuffle(app.recall.order);app.recall.index=0;app.recall.revealed=false;render();break;
      case 'recall-reveal':app.recall.revealed=true;render();break;
      case 'recall-rate':rateRecall(id,val);break;
      case 'quiz-start':startQuiz();break;
      case 'quiz-choice': {const s=app.activeQuiz;if(!s)return;const q=quizQuestion(s);s.answers[q.id]=Number(val);render();break;}
      case 'quiz-prev':if(app.activeQuiz){app.activeQuiz.current=Math.max(0,app.activeQuiz.current-1);render();}break;
      case 'quiz-next':if(app.activeQuiz){app.activeQuiz.current=Math.min(app.activeQuiz.ids.length-1,app.activeQuiz.current+1);render();}break;
      case 'quiz-jump':if(app.activeQuiz){app.activeQuiz.current=clamp(idx,0,app.activeQuiz.ids.length-1);render();}break;
      case 'quiz-submit':finishQuiz();break;
      case 'quiz-exit':if(confirm('Leave this quiz? Your unsubmitted answers will be discarded.')){clearInterval(app.timerId);app.activeQuiz=null;app.result=null;render();}break;
      case 'quiz-new':app.result=null;app.activeQuiz=null;render();break;
      case 'review-attempt': {const attempt=data.attempts.find(a=>a.id===id);if(!attempt){toast('Could not find that attempt.');return;}app.result=attempt;app.activeQuiz=null;go('quiz');break;}
      case 'scroll-results':$('#result-answers')?.scrollIntoView({behavior:'smooth',block:'start'});break;
      case 'open-add':openAddNotes();break;
      case 'open-search':openSearch();break;
      case 'open-search-result': {const l=getLesson(id);if(!l)return;const sec=el.dataset.section;go('lessons',{lesson:id});if(sec){const n=l.sections.findIndex(x=>x.title===sec);if(n>=0)setTimeout(()=>$('#section-'+n)?.scrollIntoView({behavior:'smooth'}),50);}break;}
      case 'close-modal':closeModal();break;
      case 'export':exportData();break;
      case 'import':$('#import-file').click();break;
      case 'reset':resetData();break;
      case 'delete-custom':deleteCustomLesson(id);break;
    }
  }
  document.addEventListener('click',event=>{
    const nav=event.target.closest('[data-page]');if(nav){go(nav.dataset.page);return;}
    const act=event.target.closest('[data-action]');if(act){onAction(act.dataset.action,act);return;}
    if(event.target.closest('#flip-scene')){setFlashFlipped(!app.flash.flipped);return;}
    if(event.target.matches('[data-close-modal]'))closeModal();
  });
  document.addEventListener('change',event=>{
    const el=event.target;
    switch(el.id){
      case 'flash-lesson':cancelFlashAnimation();app.flash.lesson=el.value;syncFlash(true);render();break;
      case 'flash-filter':cancelFlashAnimation();app.flash.filter=el.value;syncFlash(true);render();break;
      case 'recall-lesson':app.recall.lesson=el.value;syncRecall(true);render();break;
      case 'recall-filter':app.recall.filter=el.value;syncRecall(true);render();break;
      case 'quiz-lesson':app.quizFilters.lesson=el.value;render();break;
      case 'quiz-difficulty':app.quizFilters.difficulty=el.value;render();break;
      case 'quiz-count':app.quizFilters.count=el.value==='all'?'all':Number(el.value);render();break;
      case 'quiz-shuffle':app.quizFilters.shuffleAnswers=el.checked;break;
      case 'quiz-timed':app.quizFilters.timed=el.checked;break;
      case 'import-file':importData(el.files?.[0]);el.value='';break;
    }
  });
  document.addEventListener('input',event=>{
    const el=event.target;
    if(el.id==='lesson-search'){
      const start=el.selectionStart;app.lessonQuery=el.value;render();const newInput=$('#lesson-search');newInput?.focus();if(newInput)try{newInput.setSelectionRange(start,start);}catch{}
    }
    if(el.id==='global-query'){app.globalQuery=el.value;refreshSearch();}
  });
  document.addEventListener('submit',event=>{
    if(event.target.id!=='notes-form')return;event.preventDefault();
    const title=$('#notes-title').value.trim(),raw=$('#notes-text').value.trim();
    if(title.length<2||raw.length<5){toast('Enter a title and at least a few lines of notes.');return;}
    if(data.customLessons.length>=30){toast('Custom lesson limit reached (30). Export your data before editing.');return;}
    const l=makeCustomLesson(customId(),title,raw);data.customLessons.push(l);save();closeModal();go('lessons',{lesson:l.id});toast(`${l.customCards.length} flashcards created from term :: definition pairs.`);
  });
  document.addEventListener('keydown',event=>{
    const tag=document.activeElement?.tagName?.toLowerCase();const editing=['input','textarea','select'].includes(tag)||document.activeElement?.isContentEditable;
    const modalOpen=!$('#modal-layer').hidden;
    if(event.key==='Escape'){if(modalOpen){closeModal();event.preventDefault();return;}closeMobile();return;}
    if(!editing&&!modalOpen&&event.key==='/'){event.preventDefault();openSearch();return;}
    if(modalOpen||editing)return;
    if(app.page==='flashcards'&&app.flash.order.length&&!app.flash.finished){
      if(event.key==='ArrowRight'){event.preventDefault();onAction('flash-next',{dataset:{}});}
      else if(event.key==='ArrowLeft'){event.preventDefault();onAction('flash-prev',{dataset:{}});}
      else if(event.code==='Space'||event.key==='Enter'&&document.activeElement?.id==='flip-scene'){
        if(event.code==='Space'&&document.activeElement?.tagName==='BUTTON')return;
        event.preventDefault();setFlashFlipped(!app.flash.flipped);
      }
    }
  });
  $('#theme-toggle').addEventListener('click',setTheme);
  $('#sidebar-collapse').addEventListener('click',()=>{data.collapsed=!data.collapsed;save();refreshNav();});
  $('#sidebar-close').addEventListener('click',closeMobile);
  $('#mobile-menu').addEventListener('click',openMobile);
  $('#desktop-menu').addEventListener('click',()=>{data.collapsed=!data.collapsed;save();refreshNav();});
  $('#scrim').addEventListener('click',closeMobile);
  $('#global-search').addEventListener('click',openSearch);
  $('#add-lesson-btn').addEventListener('click',openAddNotes);
  const importer=document.createElement('input');importer.type='file';importer.accept='.json,application/json';importer.id='import-file';importer.hidden=true;document.body.append(importer);
  render();
  // Restricted, read-only test hooks used in the validation script. No user data is sent anywhere.
  Object.defineProperty(window,'__STUDYSPACE_TEST__',{value:Object.freeze({getQuestionCount:()=>BUILTIN.questions.length,getCardCount:()=>BUILTIN.cards.length,getLessonCount:()=>BUILTIN.lessons.length,getCurrentPage:()=>app.page,getAttemptCount:()=>data.attempts.length,score:(questionIds,answers)=>questionIds.reduce((n,id)=>n+(answers[id]===findQuestion(id)?.answer?1:0),0)}),writable:false});
})();
